window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-134"]=[{"id":"set2-p0eL88jH","fingerprint":"fdacf9bba42c9ef9","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt indicațiile corecte pentru utilizarea anesteziei topice în practica stomatologică?","options":[{"id":"A","text":"Incizia abceselor profund situate la nivelul planșeului bucal."},{"id":"B","text":"Extracția dinților temporari mobili, cu rizaliză accentuată."},{"id":"C","text":"Suprimarea reflexului de vomă la aplicarea materialelor de amprentă."},{"id":"D","text":"Adaptarea unei coroane la colet și finisarea unei obturații de colet."},{"id":"E","text":"Realizarea anesteziei pulpare pentru tratamentul endodontic."}],"correct":["B","C","D"],"pages":[545],"source":"set-2"},{"id":"set2-8pHesAGx","fingerprint":"dae14c361b562df1","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce adâncime de insensibilizare a țesuturilor este obținută prin anestezia topică?","options":[{"id":"A","text":"Strict la nivel intradermic."},{"id":"B","text":"Variabilă, în funcție de concentrația anestezicului, putând ajunge la nivel osos."},{"id":"C","text":"Mai puțin de 1 milimetru, acționând strict la nivelul epiteliului mucos."},{"id":"D","text":"Circa 2-3 milimetri sub mucoasă."},{"id":"E","text":"Până la 5 milimetri, permițând anestezia periostului."}],"correct":["D"],"pages":[545],"source":"set-2"},{"id":"set2-I6vSV_0S","fingerprint":"9283532c0ec7565e","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele substanțe anestezice și concentrații sunt menționate pentru utilizare în anestezia de contact?","options":[{"id":"A","text":"Tetracaină 2%."},{"id":"B","text":"Butacaină 2%."},{"id":"C","text":"Xilină în concentrație de 2%."},{"id":"D","text":"Xilină în concentrație de 5-10%."},{"id":"E","text":"Benzocaină 14%."}],"correct":["A","D","E"],"pages":[545],"source":"set-2"},{"id":"set2-K9BtjDrL","fingerprint":"b9fd2ed38be755ba","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Tehnica de anestezie prin \"imbibiție\" este utilizată pentru a insensibiliza care dintre următoarele structuri nervoase?","options":[{"id":"A","text":"Nervul alveolar inferior la nivelul foramenului mandibular."},{"id":"B","text":"Nervul mentonier la ieșirea din gaura mentonieră."},{"id":"C","text":"Plexul nervos dentar superior pentru anestezia unui incisiv central."},{"id":"D","text":"Nervul nazopalatin pe podeaua fosei nazale, prin procedeul Escat."},{"id":"E","text":"Nervul lingual în șanțul mandibulo-lingual, în dreptul molarului de minte."}],"correct":["D","E"],"pages":[545],"source":"set-2"},{"id":"set2-5RcelwaD","fingerprint":"ebdb6b0a40936293","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este un avantaj menționat al utilizării anestezicelor topice sub formă de pastă în comparație cu cele sub formă de aerosoli?","options":[{"id":"A","text":"Necesită un timp de așteptare mai redus pentru instalarea efectului."},{"id":"B","text":"Permite aprecierea exactă a cantității de anestezic folosit."},{"id":"C","text":"Produce o penetrare mai profundă a țesuturilor submucoase."},{"id":"D","text":"Timpul de instalare al anesteziei este semnificativ mai scurt."},{"id":"E","text":"Durata anesteziei este considerabil mai lungă, depășind o oră."}],"correct":["B"],"pages":[545],"source":"set-2"},{"id":"set2-Jw8guMYo","fingerprint":"8001c78b9413db9d","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele tehnici sunt considerate forme specifice de anestezie prin infiltrație în stomatologie și chirurgia oro-maxilo-facială?","options":[{"id":"A","text":"Anestezia intraosoasă și varianta sa intraseptală."},{"id":"B","text":"Anestezia intraligamentară."},{"id":"C","text":"Anestezia paraapicală supra-periostală (plexală)."},{"id":"D","text":"Anestezia topică (de contact)."},{"id":"E","text":"Anestezia prin \"imbibiție\" a nervului lingual."}],"correct":["A","B","C"],"pages":[545],"source":"set-2"},{"id":"set2-WfNigRRY","fingerprint":"f0c5e5ffa2972c97","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Conform descrierii lui Dan Theodorescu, ce tehnică anestezică este indicată pentru abcesele superficializate situate submucos?","options":[{"id":"A","text":"Anestezia intraligamentară."},{"id":"B","text":"Anestezia tronculară periferică."},{"id":"C","text":"Anestezia plexală (PAS)."},{"id":"D","text":"Anestezia topică prin badijonare."},{"id":"E","text":"Anestezia submucoasă."}],"correct":["E"],"pages":[545],"source":"set-2"},{"id":"set2-CTxyxmRj","fingerprint":"e62072e7a56df553","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt caracteristicile anesteziei submucoase utilizate pentru incizia unui abces?","options":[{"id":"A","text":"Incizia trebuie efectuată rapid, cât timp mucoasa are aspect ischemic."},{"id":"B","text":"Infiltrarea anestezicului produce ischemierea mucoasei."},{"id":"C","text":"Anestezia este de lungă durată, permițând efectuarea unor manopere complexe."},{"id":"D","text":"Senzația dureroasă poate apărea la exercitarea unei presiuni asupra periostului."},{"id":"E","text":"Acul pătrunde profund, transfixiind colecția purulentă."}],"correct":["A","B","D"],"pages":[545],"source":"set-2"},{"id":"set2-5gm2UuQ3","fingerprint":"8878d8572dbc371e","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect anestezia paraapicală supraperiostală (plexală)?","options":[{"id":"A","text":"Presupune injectarea anestezicului subperiostal pentru a bloca direct terminațiile nervoase."},{"id":"B","text":"La maxilar, este universal eficientă, inclusiv în dreptul molarului de șase ani."},{"id":"C","text":"La mandibulă, este eficientă pe toată întinderea arcadelor dentare."},{"id":"D","text":"Este mai eficientă la copii și tineri datorită unei corticale osoase mai puțin dense și a canalelor haversiene mai largi."},{"id":"E","text":"Asigură anestezia a 1-2 dinți, a mucoasei vestibulare, a periostului și a osului adiacent."}],"correct":["D","E"],"pages":[546],"source":"set-2"},{"id":"set2-TWM9yOsQ","fingerprint":"b3ef1e22f7c14c94","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce cantitate de substanță anestezică este utilizată în mod frecvent pentru anestezia plexală și pentru cea intraligamentară?","options":[{"id":"A","text":"Anestezia plexală necesită 0,15-0,20 ml de substanță anestezică."},{"id":"B","text":"Pentru anestezia intraligamentară se folosește o cantitate mai mare decât pentru cea plexală, datorită presiunii crescute de injectare."},{"id":"C","text":"Pentru anestezia plexală se folosesc 1,5-1,7 ml."},{"id":"D","text":"Pentru anestezia intraligamentară se folosesc 0,15-0,20 ml."},{"id":"E","text":"Ambele tehnici necesită o cantitate similară, de aproximativ 1,0 ml."}],"correct":["C","D"],"pages":[546],"source":"set-2"},{"id":"set2-Y5jvgI4Z","fingerprint":"8037c2be1b590fcf","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este particularitatea tehnică a anesteziei plexale pentru incisivii centrali superiori?","options":[{"id":"A","text":"Bizoul acului trebuie orientat opus față de planul osos pentru a facilita difuzia."},{"id":"B","text":"Puncția se efectuează trecând cu acul din partea opusă prin frenul buzei superioare."},{"id":"C","text":"Este necesară infiltrarea unei cantități duble de anestezic pentru a traversa sutura intermaxilară."},{"id":"D","text":"Se evită depășirea liniei mediene pentru a nu anestezia și dintele contralateral."},{"id":"E","text":"Se realizează o puncție strict în mucoasa fixă pentru a preveni formarea hematomului."}],"correct":["B"],"pages":[546],"source":"set-2"},{"id":"set2-E6cM7wct","fingerprint":"d9800d53968893d9","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"În ce situație este contraindicată anestezia paraapicală supraperiostală (plexală)?","options":[{"id":"A","text":"În cazul extracției molarului de șase ani superior, din cauza ineficienței totale."},{"id":"B","text":"La pacienții tineri, din cauza riscului de lezare a mugurilor dentari."},{"id":"C","text":"La inserarea implanturilor dentare în zona frontală maxilară."},{"id":"D","text":"Pentru rezecții apicale la dinții monoradiculari."},{"id":"E","text":"În prezența unei afecțiuni de tip supurativ la nivelul locului de puncție."}],"correct":["E"],"pages":[546],"source":"set-2"},{"id":"set2-mhM8bHJo","fingerprint":"fd6b3ae7457724d6","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt avantajele anesteziei intraligamentare?","options":[{"id":"A","text":"Este o tehnică simplă ce nu necesită instrumentar special."},{"id":"B","text":"Nu produce anestezia părților moi adiacente."},{"id":"C","text":"Teritoriul anesteziat include fibromucoasa gingivală, osul alveolar și mucoasa vestibulară a obrazului."},{"id":"D","text":"Anestezia se instalează rapid, în 25-40 de secunde."},{"id":"E","text":"Permite localizarea anesteziei la un singur dinte."}],"correct":["B","D","E"],"pages":[546],"source":"set-2"},{"id":"set2-7LwWwWeV","fingerprint":"fc1ac1a7083fe238","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce caracterizează tehnica de anestezie subcutanată „în baraj”?","options":[{"id":"A","text":"Infiltrarea anestezicului strat cu strat, direct în profunzimea ariei viitoarei plăgi operatorii."},{"id":"B","text":"Este o tehnică utilizată exclusiv pentru intervenții de mare anvergură la nivel tegumentar."},{"id":"C","text":"Infiltrarea anestezicului la distanță de leziune, creând o arie patrulateră care circumscrie plaga."},{"id":"D","text":"Sunt necesare patru puncții separate, câte una pentru fiecare vârf al patrulaterului."},{"id":"E","text":"Prin rotirea acului la 90° se realizează două laturi ale patrulaterului dintr-o singură puncție."}],"correct":["C"],"pages":[546],"source":"set-2"},{"id":"set2-pPC8O8U2","fingerprint":"79b10b0cc193fe7d","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt dezavantajele notabile ale anesteziei intraligamentare?","options":[{"id":"A","text":"Durata redusă a anesteziei, care nu depășește 15 minute."},{"id":"B","text":"Apariția frecventă a alveolitei postextracționale."},{"id":"C","text":"Necesitatea utilizării unor seringi speciale pentru administrare."},{"id":"D","text":"Durerea locală postanestezică este mai rară comparativ cu alte tehnici."},{"id":"E","text":"Risc crescut de leziuni vasculare sau nervoase prin puncții profunde."}],"correct":["B","C"],"pages":[547],"source":"set-2"},{"id":"set2--JfCt7MA","fingerprint":"70a5285fb801c7ac","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"În care dintre următoarele situații clinice este contraindicată anestezia intraligamentară?","options":[{"id":"A","text":"La pacienții cu tulburări hepatice."},{"id":"B","text":"La pacienții hemofilici."},{"id":"C","text":"La dinții permanenți pluriradiculari."},{"id":"D","text":"În prezența unei infecții la locul de puncție."},{"id":"E","text":"La pacienții sub tratament cu anticoagulante."}],"correct":["D"],"pages":[547],"source":"set-2"},{"id":"set2-kCw92ibR","fingerprint":"96e70af06eef948b","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la tehnica anesteziei intraligamentare sunt corecte?","options":[{"id":"A","text":"Acul se introduce prin papila dentară cu bizoul orientat spre spațiul interdentar."},{"id":"B","text":"Anestezicul difuzează prin osul cortical și spongios până la pachetul vasculo-nervos apical."},{"id":"C","text":"Se aplică un anestezic de contact pe papilele interdentare înainte de puncție."},{"id":"D","text":"La dinții pluriradiculari este suficientă o singură puncție vestibulară."},{"id":"E","text":"Se utilizează o seringă specială cu arc care eliberează 0,20 ml de anestezic la o apăsare."}],"correct":["B","C","E"],"pages":[547],"source":"set-2"},{"id":"set2-TbmGeu46","fingerprint":"364d66ffc17406b1","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt cauzele frecvente ale complicațiilor apărute în urma anesteziei intraligamentare?","options":[{"id":"A","text":"Difuzia lentă a anestezicului spre apexul dintelui."},{"id":"B","text":"Injectarea unui volum excesiv de anestezic local."},{"id":"C","text":"Injectarea unui volum prea mic de soluție anestezică în spațiul parodontal."},{"id":"D","text":"Utilizarea unui anestezic fără vasoconstrictor."},{"id":"E","text":"Utilizarea incorectă a seringii speciale, cu injectarea prea rapidă a soluției."}],"correct":["B","E"],"pages":[547],"source":"set-2"},{"id":"set2-preavXnS","fingerprint":"83387816fce0abc4","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este doza maximă recomandată de Articaină 4% cu adrenalină 1:100.000 pentru un dinte al unui adult (altul decât un incisiv mandibular) care necesită două puncții anestezice?","options":[{"id":"A","text":"0,23 ml (1/8 dintr-o carpulă)"},{"id":"B","text":"0,20 ml"},{"id":"C","text":"1,8 ml (o carpulă)"},{"id":"D","text":"0,9 ml (1/2 de carpulă)"},{"id":"E","text":"0,45 ml (1/4 dintr-o carpulă)"}],"correct":["D"],"pages":[547],"source":"set-2"},{"id":"set2-qL10eG6N","fingerprint":"4def53b8e39bbecc","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce avantaje prezintă sistemele de injectare intraligamentară controlate computerizat, precum sistemul STA Wand?","options":[{"id":"A","text":"Funcționează exclusiv cu seringi mecanice cu arc de tip Ligmaject."},{"id":"B","text":"Cresc eficiența anesteziei prin ghidarea poziționării acului în timp real."},{"id":"C","text":"Reduc semnificativ intensitatea dureroasă la injectare."},{"id":"D","text":"Permit administrarea unor volume mai mari de anestezic."},{"id":"E","text":"Scad predictibilitatea anesteziei prin eliminarea controlului manual."}],"correct":["B","C","D"],"pages":[547],"source":"set-2"},{"id":"set2-UQ5P0TTA","fingerprint":"0081acd2cb21c8cd","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este doza maximă de Xilină 2% cu adrenalină 1:100.000 recomandată pentru un copil de până la 30 kg, pentru un dinte temporar (altul decât un incisiv) care necesită două puncții anestezice?","options":[{"id":"A","text":"1,8 ml (o carpulă)"},{"id":"B","text":"0,23 ml (1/8 dintr-o carpulă)"},{"id":"C","text":"0,20 ml"},{"id":"D","text":"0,9 ml (1/2 de carpulă)"},{"id":"E","text":"0,45 ml (1/4 dintr-o carpulă)"}],"correct":["D"],"pages":[547],"source":"set-2"},{"id":"set2-XBDoImFB","fingerprint":"368eb7d76aa1b15d","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"În cadrul sistemului de injectare intraligamentară STA Wand, ce semnificație are culoarea verde a ledurilor de pe scala vizuală de determinare a presiunii?","options":[{"id":"A","text":"Atingerea volumului maxim de anestezic ce poate fi administrat."},{"id":"B","text":"Presiune ușoară spre moderată, optimă pentru anestezia dinților temporari."},{"id":"C","text":"Presiune minimă la vârful acului, indicând o poziționare incorectă."},{"id":"D","text":"Presiune mare la nivelul spațiului parodontal."},{"id":"E","text":"O eroare a sistemului care necesită recalibrare."}],"correct":["D"],"pages":[548],"source":"set-2"},{"id":"set2-v6J7ke2k","fingerprint":"470f21c7fa9acc50","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la anestezia intraosoasă sunt corecte?","options":[{"id":"A","text":"Durata anesteziei este constantă, de aproximativ 60 de minute."},{"id":"B","text":"Riscul de injectare intravasculară este considerat mic, sub 5%."},{"id":"C","text":"Se instalează rapid, în aproximativ 30 de secunde."},{"id":"D","text":"Este indicată evitarea injectării în apropierea orificiului mentonier."},{"id":"E","text":"Produce anestezia limbii și a mucoasei labiale."}],"correct":["B","C","D"],"pages":[548],"source":"set-2"},{"id":"set2-ivzAYv-r","fingerprint":"25eaf5fd7bc78461","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce caracteristici specifice sunt asociate cu utilizarea sistemului X-Tip pentru anestezia intraosoasă?","options":[{"id":"A","text":"Se recomandă administrarea a circa 0,5 ml de soluție anestezică pentru tratamentul limitat la 1-2 dinți."},{"id":"B","text":"Procedeul permite anestezia strict a unui singur dinte, indiferent de volumul de soluție injectat."},{"id":"C","text":"Sistemul este format dintr-o singură componentă, o piesă de mână cu perforator integrat."},{"id":"D","text":"Componenta de ghidaj rămâne pe loc pe toată durata intervenției stomatologice pentru a facilita reinjectarea."},{"id":"E","text":"Datorită vascularizației reduse a osului spongios, se utilizează vasoconstrictoare în concentrație mare (1:50.000)."}],"correct":["A"],"pages":[548],"source":"set-2"},{"id":"set2-0Q5wDWUL","fingerprint":"27203ec682835013","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este mecanismul de producere a unui orificiu fistulos, o complicație rară a anesteziei intraosoase?","options":[{"id":"A","text":"Injectarea unui volum excesiv de soluție anestezică, care produce necroză de presiune."},{"id":"B","text":"Utilizarea intempestivă a piesei de mână cu presiune necontrolată, ducând la acumulare de căldură și necroză osoasă superficială."},{"id":"C","text":"O reacție alergică localizată la componenta de ghidaj a sistemului X-Tip."},{"id":"D","text":"Perforarea accidentală a rădăcinii unui dinte adiacent în timpul procedurii."},{"id":"E","text":"O infecție secundară a locului de puncție, cauzată de o asepsie deficitară."}],"correct":["B"],"pages":[548],"source":"set-2"},{"id":"set2-0VX01Pzi","fingerprint":"8319a37ef86e5d04","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce deosebește fundamental tehnica de anestezie intraosoasă de cea intraligamentară în ceea ce privește echipamentul utilizat?","options":[{"id":"A","text":"Nu există nicio diferență fundamentală de echipament, ambele tehnici putând fi realizate cu o seringă standard."},{"id":"B","text":"Anestezia intraligamentară utilizează un perforator cu mandren, în timp ce cea intraosoasă folosește o seringă specială cu arc."},{"id":"C","text":"Ambele tehnici utilizează același tip de seringă, diferența fiind doar presiunea de injectare controlată computerizat."},{"id":"D","text":"Anestezia intraosoasă se realizează exclusiv cu sisteme computerizate, pe când cea intraligamentară se face doar cu seringi mecanice."},{"id":"E","text":"Anestezia intraosoasă presupune utilizarea unui perforator pentru a traversa corticala osoasă, în timp ce cea intraligamentară utilizează o seringă specială cu arc."}],"correct":["E"],"pages":[548],"source":"set-2"},{"id":"set2-uFDG4TOS","fingerprint":"f1c5e48600b02ef6","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt avantajele sistemelor de injectare intraligamentară controlate computerizat, precum STA Wand, comparativ cu tehnicile convenționale?","options":[{"id":"A","text":"Reduc durata de instalare a anesteziei la sub 10 secunde."},{"id":"B","text":"Reducerea semnificativă a intensității dureroase la injectare."},{"id":"C","text":"Imposibilitatea utilizării la dinții temporari pentru a proteja dintele permanent."},{"id":"D","text":"Permit administrarea de volume mai mari de anestezic, crescând durata și eficiența."},{"id":"E","text":"Oferă feedback în timp real despre poziționarea acului, crescând predictibilitatea anesteziei."}],"correct":["B","D","E"],"pages":[548],"source":"set-2"},{"id":"set2-RwPcMMz4","fingerprint":"06819ce498d373c9","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce caracteristici descriu procedura de realizare a anesteziei intraosoase cu sistemul Stabident?","options":[{"id":"A","text":"Înainte de perforarea corticalei, se realizează o anestezie locală de contact la nivelul mucoasei."},{"id":"B","text":"Cateterizarea orificiului creat de perforator este descrisă ca fiind o manevră simplă în toate cazurile."},{"id":"C","text":"Anestezicul se injectează printr-un ac lung, flexibil, pentru a naviga prin osul spongios."},{"id":"D","text":"Sistemul utilizează o componentă de ghidaj care se separă după perforare."},{"id":"E","text":"Perforatorul este acționat la viteză mare (peste 100.000 rpm) pentru a minimiza disconfortul."}],"correct":["A"],"pages":[548],"source":"set-2"},{"id":"set2-2ai19-13","fingerprint":"54a54cdedf62e7b7","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt indicațiile anesteziei intraseptale?","options":[{"id":"A","text":"Intervențiile restaurative minime efectuate pe dinții mandibulari posteriori."},{"id":"B","text":"Situațiile în care este prezentă o inflamație severă la locul puncției."},{"id":"C","text":"Procedurile de chirurgie parodontală, pentru anestezia osului și a părților moi."},{"id":"D","text":"Extirparea pulpară în caz de pulpita acută ireversibilă la molarii mandibulari."},{"id":"E","text":"Asigurarea hemostazei în parodontopatiile marginale cronice profunde."}],"correct":["A","C","E"],"pages":[549],"source":"set-2"},{"id":"set2-ELj-S4EK","fingerprint":"24b2c20d28b637d6","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce parametrii specifici caracterizează tehnica de anestezie intraseptală în ceea ce privește cantitatea de soluție și timpul de injectare?","options":[{"id":"A","text":"Se depozitează o cantitate de 0,2-0,3 ml timp de 20 de secunde."},{"id":"B","text":"Se injectează fără presiune câteva picături, urmate de 0,2 ml timp de 20 de secunde."},{"id":"C","text":"Se depozitează 0,4 ml de anestezic într-un interval lent de 20 de secunde."},{"id":"D","text":"Se insinuează acul 1-2 mm în septul interdentar și se injectează 0,4 ml în 30 de secunde."},{"id":"E","text":"Se injectează 0,2-0,3 ml de anestezic într-un interval rapid de 30 de secunde."}],"correct":["C"],"pages":[549],"source":"set-2"},{"id":"set2-amwmTLCU","fingerprint":"d2a61dd4480b8469","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care dintre următoarele afirmații descrie corect o caracteristică a anesteziei intrapulpare?","options":[{"id":"A","text":"Principalul avantaj este hemostaza eficientă în țesuturile moi adiacente."},{"id":"B","text":"Tehnica este contraindicată la molarii mandibulari din cauza riscului de infecție."},{"id":"C","text":"Procedeul poate fi efectuat doar dacă există o expunere a camerei pulpare."},{"id":"D","text":"Mecanismul de acțiune este similar cu cel al anesteziei intraligamentare."},{"id":"E","text":"Durata medie a efectului anestezic este de 20-25 de minute."}],"correct":["C"],"pages":[549],"source":"set-2"},{"id":"set2-imvjenxi","fingerprint":"e3e44d18f27a9c05","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt avantajele anesteziei intrapulpare?","options":[{"id":"A","text":"Durata de acțiune prelungită, de peste 30 de minute."},{"id":"B","text":"Procedura este complet nedureroasă pentru pacient."},{"id":"C","text":"Lipsa anestezierii concomitente a părților moi."},{"id":"D","text":"Instalarea rapidă a efectului anestezic, în aproximativ 30 de secunde."},{"id":"E","text":"Absența riscului de injectare intravasculară."}],"correct":["C","D","E"],"pages":[549],"source":"set-2"},{"id":"set2-QFletpxN","fingerprint":"721417cd81451513","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce aspect tehnic este specific anesteziei intraseptale?","options":[{"id":"A","text":"Poziționarea bizoului acului spre coroana dintelui."},{"id":"B","text":"Obținerea anesteziei prin efect farmacologic și prin presiunea de injectare în canalele radiculare."},{"id":"C","text":"Depozitarea sub presiune a 0,2-0,3 ml de soluție anestezică."},{"id":"D","text":"Inserarea fermă a acului direct în camera pulpară expusă."},{"id":"E","text":"Puncționarea papilei interdentare cu acul orientat la 45 de grade față de axul lung al dintelui."}],"correct":["E"],"pages":[549],"source":"set-2"},{"id":"set2-E0TLAkN9","fingerprint":"2d28eae359247c4c","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este un dezavantaj major al anesteziei intrapulpare?","options":[{"id":"A","text":"Risc crescut de injectare intravasculară."},{"id":"B","text":"Puncția anestezică este asociată cu o scurtă perioadă de durere intensă."},{"id":"C","text":"Instalarea lentă a efectului anestezic."},{"id":"D","text":"Anesteziază o suprafață extinsă de părți moi."},{"id":"E","text":"Necesită un volum mare de soluție anestezică (peste 1 ml)."}],"correct":["B"],"pages":[549],"source":"set-2"},{"id":"set2-Sj0KY47_","fingerprint":"cd4adde346c3f177","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt afirmațiile corecte referitoare la procedura de anestezie prin injecție intrapulpară?","options":[{"id":"A","text":"Pentru un acces optim la nivelul canalelor radiculare, poate fi necesară îndoirea acului."},{"id":"B","text":"Fracturarea acului este un incident frecvent, iar fragmentul restant este de obicei dificil de îndepărtat."},{"id":"C","text":"Injectarea soluției anestezice este urmată de o scurtă perioadă de sensibilitate dureroasă, uneori intensă."},{"id":"D","text":"Instrumentarea mecanică a spațiului endodontic poate începe la aproximativ 30 de secunde de la injectare."},{"id":"E","text":"Sensibilitatea dureroasă apărută la injectare dispare de obicei rapid."}],"correct":["A","C","D","E"],"pages":[550],"source":"set-2"},{"id":"set2-zvw4X2yA","fingerprint":"23587d004b5ef55a","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce element fundamental diferențiază anestezia tronculară periferică de alte tipuri de anestezii care se adresează filetelor nervoase terminale?","options":[{"id":"A","text":"Deformează regiunea anesteziată prin infiltrarea unui volum mare de soluție."},{"id":"B","text":"Acționează pe traiectul unui nerv întrerupând conductibilitatea."},{"id":"C","text":"Vizează trunchiul nervos și ramurile sale."},{"id":"D","text":"Are o durată de acțiune mai scurtă."},{"id":"E","text":"Este o tehnică de anestezie bazală, utilizată la ieșirea nervilor din baza craniului."}],"correct":["B","C"],"pages":[550],"source":"set-2"},{"id":"set2-Lsdh1Kj0","fingerprint":"762fd592377a18e4","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele afirmații despre anestezia tronculară sunt adevărate?","options":[{"id":"A","text":"Reperele principale, sau esențiale, sunt reprezentate de elementele osoase ale craniului."},{"id":"B","text":"Reperele secundare sunt constituite din dinți și părți moi."},{"id":"C","text":"Anestezia nervului mandibular la ieșirea prin gaura ovală constituie o anestezie tronculară bazală."},{"id":"D","text":"Reperele principale rămân stabile pe tot parcursul vieții."},{"id":"E","text":"Anestezia tronculară bazală la nivelul găurii ovale este o tehnică de rutină în chirurgia oro-maxilo-facială actuală."}],"correct":["A","B","C","D"],"pages":[550],"source":"set-2"},{"id":"set2-_-3uwgol","fingerprint":"499d09cca51fc56c","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce teritoriu este anesteziat în urma efectuării anesteziei nervilor alveolari supero-posteriori, cunoscută și ca anestezia „la tuberozitate”?","options":[{"id":"A","text":"Molarii superiori, osul alveolar și fibromucoasa vestibulară adiacentă."},{"id":"B","text":"Constant, se produce și anestezia ramului mandibular al nervului trigemen."},{"id":"C","text":"Peretele posterior al sinusului maxilar și mucoasa sinusală adiacentă."},{"id":"D","text":"Rădăcina mezio-vestibulară a molarului de 6 ani în toate cazurile."},{"id":"E","text":"Uneori, anestezia se poate instala parțial sau total și în zona premolarilor."}],"correct":["A","C","E"],"pages":[550],"source":"set-2"},{"id":"set2-3lUQpZ4R","fingerprint":"7c27e62feab3e402","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele reprezintă o contraindicație specifică pentru anestezia „la tuberozitate”?","options":[{"id":"A","text":"Pacienții sub tratament cu anticoagulante."},{"id":"B","text":"Pacienți cu risc hemoragic, din cauza proximității plexului venos pterigoidian."},{"id":"C","text":"Prezența unor procese inflamatorii sau tumorale retrotuberozitar."},{"id":"D","text":"Ineficiența anesteziei plexale în regiunea molarilor superiori."},{"id":"E","text":"Necesitatea efectuării unor manopere terapeutice pe un teritoriu extins."}],"correct":["A","B","C"],"pages":[550],"source":"set-2"},{"id":"set2-iSFA6aH9","fingerprint":"62737b14c4a5fbf5","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce caracteristică descrie corect calea cutanată de efectuare a anesteziei nervilor alveolari supero-posteriori?","options":[{"id":"A","text":"Puncția se realizează deasupra marginii inferioare a osului zigomatic."},{"id":"B","text":"Puncția se face sub marginea inferioară a osului zigomatic și distal de creasta zigomato-alveolară."},{"id":"C","text":"Puncția anestezică se face în obraz, înaintea mușchiului maseter."},{"id":"D","text":"Este o tehnică utilizată frecvent în stomatologia actuală."},{"id":"E","text":"Acul trebuie să perforeze mucoasa jugală pentru a ajunge la nerv."}],"correct":["B","C"],"pages":[550],"source":"set-2"},{"id":"set2-HnhWzHUQ","fingerprint":"fd8887e8ec7a678d","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt afirmațiile corecte referitoare la hematomul la tuberozitate?","options":[{"id":"A","text":"Tratamentul de urgență constă în comprimarea obrazului sub osul zigomatic cu podul palmei."},{"id":"B","text":"Se formează în urma înțepării cu acul a plexului venos pterigoidian."},{"id":"C","text":"Cauza principală a apariției sale este injectarea unei cantități prea mari de anestezic."},{"id":"D","text":"Are un caracter lent extensiv, fiind limitat de spațiul osos pterigo-maxilar."},{"id":"E","text":"Se indică tratament medicamentos antibiotic și antiinflamator pentru a preveni suprainfectarea."}],"correct":["A","B","E"],"pages":[551],"source":"set-2"},{"id":"set2-rHYgRqHA","fingerprint":"f96361e2dd48fcbe","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este direcția corectă a acului și unghiul format cu planul de ocluzie în timpul anesteziei „la tuberozitate”?","options":[{"id":"A","text":"Oblic în jos, înainte și în afară, formând un unghi de 90°."},{"id":"B","text":"Oblic în sus, înapoi și în afară, formând un unghi de 30°."},{"id":"C","text":"Paralel cu planul de ocluzie, strict înapoi și înăuntru."},{"id":"D","text":"Perpendicular pe planul de ocluzie, strict în sus."},{"id":"E","text":"Oblic în sus, înapoi și înăuntru, formând un unghi de 45°."}],"correct":["E"],"pages":[551],"source":"set-2"},{"id":"set2-ExTMKKpG","fingerprint":"19b71ceb96d3951c","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce afirmații sunt adevărate cu privire la anestezia nervului nazopalatin?","options":[{"id":"A","text":"Teritoriul anesteziat se referă la treimea anterioară a fibromucoasei palatine, delimitată posterior de o linie de la canin la canin."},{"id":"B","text":"Pentru extracția caninului superior, este suficientă doar anestezierea nervului nazopalatin."},{"id":"C","text":"Anestezia sa determină insensibilizarea mucoasei palatinale de la linia mediană până la caninul de partea respectivă, inclusiv."},{"id":"D","text":"Nervul nazopalatin al lui Scarpa iese în boltă prin orificiul canalului nazopalatin, situat la 1 cm posterior de limbusul interalveolar interincisiv central."},{"id":"E","text":"Este indicată în mod izolat pentru intervenții chirurgicale la nivelul grupului frontal superior."}],"correct":["A","C","D"],"pages":[551],"source":"set-2"},{"id":"set2-R2fjH8Tj","fingerprint":"dc92065d9601e3dd","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Conform tehnicii de anestezie „la tuberozitate”, care dintre următoarele manevre este corectă?","options":[{"id":"A","text":"Puncția se face în mucoasa fixă, deasupra rădăcinii distale a molarului de 6 ani."},{"id":"B","text":"Mandibula este deviată de partea unde se va face puncția anestezică."},{"id":"C","text":"Pacientul este poziționat cu gura larg deschisă pentru a vizualiza mai bine reperele."},{"id":"D","text":"Se injectează rapid o cantitate de 3-4 ml de soluție anestezică."},{"id":"E","text":"După ce se ia contact cu osul, acul se retrage 1-2 mm pentru a evita injectarea subperiostală."}],"correct":["B"],"pages":[551],"source":"set-2"},{"id":"set2-DLikG1BV","fingerprint":"f0b9ab722efd68a5","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Unde este localizat punctul precis de puncție anestezică pentru anestezia la gaura incisivă?","options":[{"id":"A","text":"În șanțul vestibular superior, în dreptul incisivilor centrali."},{"id":"B","text":"Pe linia mediană, palatinal, la 0,5 cm înapoia și deasupra coletului incisivilor centrali superiori."},{"id":"C","text":"Lateral de papila incisivă, pentru a evita structurile vasculare de pe linia mediană."},{"id":"D","text":"La intersecția liniei mediene cu o linie transversală ce unește caninii."},{"id":"E","text":"La 1 cm posterior de papila incisivă, direct în canalul nazopalatin."}],"correct":["B"],"pages":[551],"source":"set-2"},{"id":"set2-AHAsIfTW","fingerprint":"e0a3d41b705d93e4","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce descriere anatomică a canalelor incisive este corectă?","options":[{"id":"A","text":"Au o traiectorie strict verticală de la fosele nazale la cavitatea orală."},{"id":"B","text":"Au o direcție oblică în sus, înapoi și în afară, iar pe secțiune frontală au o imagine de „V” sau „Y”."},{"id":"C","text":"Sunt două canale paralele care se deschid separat pe planșeul foselor nazale."},{"id":"D","text":"Sunt despărțite printr-o lamă osoasă groasă și conțin exclusiv nervul palatin mare."},{"id":"E","text":"Se unesc la nivelul planșeului foselor nazale și se deschid în cavitatea orală printr-un singur orificiu."}],"correct":["B"],"pages":[551],"source":"set-2"},{"id":"set2-SMqXshRk","fingerprint":"ca795d0564eeee98","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt factorii care contribuie la durerea resimțită în timpul puncției anestezice pentru nervul nazopalatin?","options":[{"id":"A","text":"Prezența unui strat gros de țesut adipos sub mucoperiost."},{"id":"B","text":"Inervația bogată de la nivelul papilei incisive."},{"id":"C","text":"Lipsa țesutului conjunctiv la nivelul zonei puncționate."},{"id":"D","text":"Proximitatea podelei foselor nazale."},{"id":"E","text":"Aderența fibromucoasei palatine la planul osos."}],"correct":["B","C","E"],"pages":[552],"source":"set-2"},{"id":"set2-FxQhxkuV","fingerprint":"eb41495f93ca328d","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Conform tehnicii standard de anestezie a nervului nazopalatin, care este direcția corectă a acului după puncție?","options":[{"id":"A","text":"În sus, înainte și în afară."},{"id":"B","text":"Paralel cu axul incisivului central."},{"id":"C","text":"Strict perpendicular pe planul osos."},{"id":"D","text":"În jos, înainte și spre linia mediană."},{"id":"E","text":"În sus, înapoi și în afară."}],"correct":["E"],"pages":[552],"source":"set-2"},{"id":"set2-k68nZ5UV","fingerprint":"8ddc7a94b8c40fa2","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce presupune tehnica modificată descrisă de Malamed pentru anestezia nervului nazopalatin, menită să fie mai puțin dureroasă?","options":[{"id":"A","text":"Anestezia prin imbibiție (de contact) a nervului pe podeaua fosei nazale."},{"id":"B","text":"O puncție inițială la nivelul frenului labial superior, urmată de o puncție în papila interdentară dintre incisivii centrali."},{"id":"C","text":"Injectarea unei cantități de 0,5 ml anestezic direct în papila incisivă fără anestezie de contact."},{"id":"D","text":"Puncția mucoasei nazale înapoia pragului narinar cutanat."},{"id":"E","text":"O puncție unică, profundă, direct în canalul incisiv, cu un volum mare de anestezic."}],"correct":["B"],"pages":[552],"source":"set-2"},{"id":"set2-PyX8yQaD","fingerprint":"72542d3b772dfd50","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce teritoriu este anesteziat prin blocajul nervului palatin mare (anterior)?","options":[{"id":"A","text":"Vălul moale și cârligul aripii interne a apofizei pterigoide."},{"id":"B","text":"Gingia vestibulară de la nivelul incisivilor centrali superiori."},{"id":"C","text":"Fibromucoasa palatină din regiunea anterioară, distal de canin."},{"id":"D","text":"Fibromucoasa palatină din cele 2/3 posterioare, la nivelul premolarilor și molarilor."},{"id":"E","text":"Mucoasa de pe podeaua foselor nazale."}],"correct":["D"],"pages":[552],"source":"set-2"},{"id":"set2-RqGqkCw_","fingerprint":"9abc0ee35a5066e6","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele reprezintă repere utilizate pentru localizarea găurii palatine mari în vederea anesteziei nervului palatin mare?","options":[{"id":"A","text":"La 1 cm deasupra coletului ultimului molar."},{"id":"B","text":"În unghiul diedru format de creasta alveolară cu lama orizontală a osului palatin."},{"id":"C","text":"La nivelul frenului labial superior."},{"id":"D","text":"La 0,5 cm înaintea marginii posterioare a palatului dur."},{"id":"E","text":"La 0,5 cm înapoia marginii gingivale a incisivilor centrali."}],"correct":["A","B","D"],"pages":[552],"source":"set-2"},{"id":"set2-IkMf_IkS","fingerprint":"f444549eab00bc07","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce accidente minore pot apărea în timpul anesteziei nervului palatin mare?","options":[{"id":"A","text":"Hemoragie prin înțeparea vaselor palatine."},{"id":"B","text":"Edem tranzitoriu al vălului moale."},{"id":"C","text":"Perforarea podelei fosei nazale."},{"id":"D","text":"Anestezia nervului maxilar."},{"id":"E","text":"Necroză limitată a fibromucoasei palatine."}],"correct":["A","B","E"],"pages":[552],"source":"set-2"},{"id":"set2-L5JnwVPT","fingerprint":"554b30ac48d46a0a","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este principalul factor de risc pentru apariția necrozei de mucoasă în cazul anesteziei prin infiltrație a fibromucoasei palatine?","options":[{"id":"A","text":"Pătrunderea acului până la nivelul osului."},{"id":"B","text":"Puncția realizată la mai puțin de 1 cm de marginea gingivală."},{"id":"C","text":"Utilizarea unei soluții anestezice fără vasoconstrictor."},{"id":"D","text":"Folosirea unui ac cu diametru prea mare."},{"id":"E","text":"Injectarea bruscă a unei cantități mari de anestezic."}],"correct":["E"],"pages":[552],"source":"set-2"},{"id":"set2-ul_fmqDI","fingerprint":"899261f700fe0175","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele structuri anatomice sunt anesteziate în urma unei anestezii reușite a nervului infraorbital?","options":[{"id":"A","text":"Gingivomucoasa vestibulară mandibulară de la gaura mentonieră la linia mediană."},{"id":"B","text":"Dinții frontali superiori (incisiv central, lateral, canin)."},{"id":"C","text":"Pleoapa inferioară."},{"id":"D","text":"Mucoasa vestibulară distal de gaura mentonieră."},{"id":"E","text":"Jumătate din buza superioară și aripa nasului."}],"correct":["B","C","E"],"pages":[553],"source":"set-2"},{"id":"set2-zW6SPjJo","fingerprint":"6b9dc9050d14cf6a","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce rol are nervul alveolar supero-mijlociu, atunci când este prezent?","options":[{"id":"A","text":"Inervează fibromucoasa palatină."},{"id":"B","text":"Asigură sensibilitatea dinților frontali superiori."},{"id":"C","text":"Contribuie la inervația pleoapei inferioare și a aripii nasului."},{"id":"D","text":"Asigură inervația mucoasei vestibulare din dreptul molarilor mandibulari."},{"id":"E","text":"Asigură inervația premolarilor și a rădăcinii mezio-vestibulare a primului molar."}],"correct":["E"],"pages":[553],"source":"set-2"},{"id":"set2-L1In49FJ","fingerprint":"46dab2897096ec1e","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele repere anatomice sunt utilizate pentru localizarea găurii infraorbitare?","options":[{"id":"A","text":"La unirea celor 2/3 interne cu 1/3 externă a marginii infraorbitale."},{"id":"B","text":"La 5 mm înăuntrul liniei verticale mediopupilare."},{"id":"C","text":"La 6 - 8 mm sub rebordul orbitar inferior."},{"id":"D","text":"Pe aceeași verticală cu gaura mandibulară (spina Spix)."},{"id":"E","text":"Pe linia verticală care trece între cei doi premolari superiori."}],"correct":["B","C","E"],"pages":[553],"source":"set-2"},{"id":"set2-D0xwskTc","fingerprint":"2f1edb0e02328a83","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"În timpul anesteziei nervului infraorbital pe cale orală, care este adâncimea de pătrundere necesară în canal pentru a obține anestezia dinților frontali?","options":[{"id":"A","text":"6 - 10 mm"},{"id":"B","text":"Nu este necesară pătrunderea în canal."},{"id":"C","text":"0,5 - 1 mm"},{"id":"D","text":"2 - 4 mm"},{"id":"E","text":"Peste 15 mm"}],"correct":["A"],"pages":[553],"source":"set-2"},{"id":"set2-SaVoCsLK","fingerprint":"324fd3fb2b715ac7","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce poate cauza apariția diplopiei tranzitorii în urma unei anestezii a nervului infraorbital prin abord cutanat?","options":[{"id":"A","text":"Injectarea substanței anestezice în grăsimea orbitară prin anestezia ramurii inferioare a nervului oculomotor comun."},{"id":"B","text":"Anestezia nervului optic prin pătrunderea acului în orbită."},{"id":"C","text":"Contactul acului cu planul osos inferior de gaura infraorbitală."},{"id":"D","text":"Anestezia ramurilor terminale labiale și nazale."},{"id":"E","text":"Puncția anestezică practicată în fosa canină."}],"correct":["A"],"pages":[553],"source":"set-2"},{"id":"set2-WA195wHy","fingerprint":"9a494a2acc778f39","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"În cazul unei intervenții chirurgicale la nivelul unui incisiv central superior, ce anestezie suplimentară este frecvent necesară pe lângă blocajul nervului infraorbital?","options":[{"id":"A","text":"Anestezia nervului bucal."},{"id":"B","text":"Anestezia plexală vestibulară sau a nervului nazo-palatin."},{"id":"C","text":"Anestezia nervului maseterin."},{"id":"D","text":"Anestezia nervului mentonier."},{"id":"E","text":"Anestezia la spina Spix."}],"correct":["B"],"pages":[553],"source":"set-2"},{"id":"set2-0gWT7oll","fingerprint":"480b54700ffad28b","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce consecință are contactul acului cu planul osos inferior de gaura infraorbitală, fără a pătrunde în canal?","options":[{"id":"A","text":"Lipsa temporară a vederii."},{"id":"B","text":"Anestezia fibromucoasei palatine."},{"id":"C","text":"Diplopie tranzitorie."},{"id":"D","text":"Anestezia pleoapei inferioare, a aripii nazale și a buzei superioare, dar nu și a dinților."},{"id":"E","text":"Anestezia completă, atât a dinților, cât și a părților moi."}],"correct":["D"],"pages":[553],"source":"set-2"},{"id":"set2-6wVY6uUY","fingerprint":"dfc06773fc40a83b","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este teritoriul specific exceptat de la anestezia obținută printr-un blocaj al nervului alveolar inferior la spina Spix?","options":[{"id":"A","text":"Părțile moi labio-mentoniere."},{"id":"B","text":"Gingivomucoasa vestibulară de la gaura mentonieră la linia mediană."},{"id":"C","text":"Osul și dinții de pe o hemiarcadă mandibulară."},{"id":"D","text":"Mucoasa vestibulară mezial de gaura mentonieră."},{"id":"E","text":"Mucoasa vestibulară distal de gaura mentonieră."}],"correct":["E"],"pages":[553],"source":"set-2"},{"id":"set2-ez_rffxd","fingerprint":"0eb1faa1eb4023f6","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt reperele anatomice utilizate pentru localizarea spinei Spix în vederea anesteziei nervului alveolar inferior?","options":[{"id":"A","text":"Planul de ocluzie al molarilor inferiori"},{"id":"B","text":"Linia oblică externă a mandibulei"},{"id":"C","text":"Creasta temporală"},{"id":"D","text":"Plica pterigomandibulară"},{"id":"E","text":"Marginea anterioară a mușchiului maseter"}],"correct":["A","C","D"],"pages":[554],"source":"set-2"},{"id":"set2-vAaKF0Ci","fingerprint":"f6a76327c29e0b27","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este localizarea corectă a locului de puncție pentru anestezia la spina Spix la un pacient adult dentat?","options":[{"id":"A","text":"Exact în centrul plicii pterigomandibulare, la 1 cm sub planul de ocluzie."},{"id":"B","text":"Între creasta temporală și plica pterigomandibulară, la 1 cm deasupra planului de ocluzie al molarilor inferiori."},{"id":"C","text":"Lateral de creasta temporală, la 0,5 cm deasupra planului de ocluzie al molarilor inferiori."},{"id":"D","text":"Medial de plica pterigomandibulară, la nivelul planului de ocluzie al molarilor inferiori."},{"id":"E","text":"Între marginea anterioară a ramului mandibular și creasta temporală, la 1,5 cm deasupra planului de ocluzie."}],"correct":["B"],"pages":[554],"source":"set-2"},{"id":"set2-55rlXT5H","fingerprint":"00bb50d4fca93cbb","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"În timpul tehnicii clasice de anestezie a nervului alveolar inferior, cum progresează acul și corpul seringii după realizarea contactului osos inițial?","options":[{"id":"A","text":"Acul se retrage după contactul osos și se reintroduce mai medial, în timp ce corpul seringii rămâne paralel cu arcada inferioară."},{"id":"B","text":"Acul rămâne fix după contactul osos, iar anestezicul este injectat lent pentru a difuza spre nerv."},{"id":"C","text":"Acul avansează liber prin spațiul pterigomandibular, iar corpul seringii rămâne fix în dreptul molarilor de pe partea anesteziată."},{"id":"D","text":"Acul avansează în contact cu osul pe fața externă a ramului mandibular, iar corpul seringii se deplasează spre posterior."},{"id":"E","text":"Acul avansează în contact cu osul pe fața internă a ramului mandibular, iar corpul seringii se deplasează progresiv spre linia mediană a mandibulei."}],"correct":["E"],"pages":[554],"source":"set-2"},{"id":"set2-oapFPT1J","fingerprint":"8e812f6257fb38bb","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce consecințe pot apărea în urma unei puncții efectuate prea profund (2,5-3 cm) sau prea sus în timpul anesteziei la spina Spix?","options":[{"id":"A","text":"Puncția prea profundă poate infiltra glanda parotidă, cauzând pareza tranzitorie a nervului facial."},{"id":"B","text":"Puncția efectuată mai sus poate determina anestezia nervului auriculotemporal."},{"id":"C","text":"Puncția efectuată mai sus poate cauza paralizia mușchiului maseter."},{"id":"D","text":"Puncția efectuată mai sus duce la proptirea acului în marginea anterioară a ramului mandibular."},{"id":"E","text":"Puncția prea profundă poate duce la anestezia laterofaringelui și tulburări de deglutiție."}],"correct":["A","B","C"],"pages":[554],"source":"set-2"},{"id":"set2-ptr1cKRo","fingerprint":"64672c64ae27fd31","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce se întâmplă dacă puncția pentru anestezia nervului alveolar inferior este efectuată prea medial (înăuntru) de plica pterigomandibulară?","options":[{"id":"A","text":"Se produce pareza tranzitorie a nervului facial."},{"id":"B","text":"Se anesteziază nervul auriculotemporal și pavilionul auricular."},{"id":"C","text":"Acul se propteste în marginea anterioară a ramului mandibular."},{"id":"D","text":"Anestezia nu se instalează deoarece acul nu interceptează nervul."},{"id":"E","text":"Se produce anestezie la nivelul laterofaringelui, însoțită de tulburări de deglutiție."}],"correct":["E"],"pages":[554],"source":"set-2"},{"id":"set2-lcaqTUmV","fingerprint":"f6a93e09b94c0720","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele reprezintă accidente posibile ale puncției anestezice la spina Spix?","options":[{"id":"A","text":"Tulburări de deglutiție."},{"id":"B","text":"Înțeparea pachetului vasculo-nervos cu producerea unui hematom."},{"id":"C","text":"Producerea unei nevrite tranzitorii."},{"id":"D","text":"Paralizia mușchiului maseter."},{"id":"E","text":"Injectarea intravasculară a substanței anestezice."}],"correct":["B","C","E"],"pages":[554],"source":"set-2"},{"id":"set2-sEmwddP2","fingerprint":"6e481007cd63f502","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt variantele anatomice care pot contribui la eșecul anesteziei la spina Spix?","options":[{"id":"A","text":"Inervația accesorie a rădăcinii meziale a molarului unu inferior din nervul milohioidian."},{"id":"B","text":"Prezența unui canal mandibular bifid cu un orificiu mandibular accesoriu."},{"id":"C","text":"O plică pterigomandibulară foarte proeminentă care deviază acul."},{"id":"D","text":"O creastă temporală foarte ascuțită care blochează progresia acului."},{"id":"E","text":"Încrucișarea fibrelor nervoase de la nervul alveolar inferior contralateral la nivelul incisivilor."}],"correct":["A","B","E"],"pages":[554],"source":"set-2"},{"id":"set2-08GxOY1d","fingerprint":"0a6eb401227f3b5b","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce manevră de corecție este indicată atunci când o puncție efectuată mai jos decât reperul corect nu produce anestezie?","options":[{"id":"A","text":"Se așteaptă o perioadă mai lungă pentru instalarea efectului."},{"id":"B","text":"Se redirecționează vârful acului spre posterior, menținând adâncimea."},{"id":"C","text":"Se avansează cu acul la o profunzime de 2,5-3 cm."},{"id":"D","text":"Se reinjectează la 0,5-1 cm superior de locul puncției inițiale."},{"id":"E","text":"Se retrage acul și se puncționează mai medial de plica pterigomandibulară."}],"correct":["D"],"pages":[554],"source":"set-2"},{"id":"set2-iHfCvVqT","fingerprint":"e855590972383251","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce semne sistemice pot indica o injectare intravasculară accidentală în timpul anesteziei nervului alveolar inferior?","options":[{"id":"A","text":"Tahicardie, paloare și lipotimie."},{"id":"B","text":"Anestezia pavilionului auricular."},{"id":"C","text":"Dificultăți la înghițire."},{"id":"D","text":"Apariția unui hematom în regiunea puncției."},{"id":"E","text":"Pareza tranzitorie a feței."}],"correct":["A"],"pages":[554],"source":"set-2"},{"id":"set2-HozESp1V","fingerprint":"92e87c8f1e84d612","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este localizarea precisă a locului de puncție pentru anestezia nervului alveolar inferior pe cale submandibulară?","options":[{"id":"A","text":"La 1,5 cm de marginea anterioară a ramului vertical și la 1,5 cm deasupra unghiului mandibular."},{"id":"B","text":"La 1,5 cm de marginea posterioară a ramului vertical, la 1,5 cm de unghiul mandibular și la 1,5 cm sub marginea inferioară a mandibulei."},{"id":"C","text":"La intersecția plicii pterigomandibulare cu planul de ocluzie al molarilor inferiori."},{"id":"D","text":"Sub lobul urechii, la jumătatea distanței dintre arcada temporo-zigomatică și gonion."},{"id":"E","text":"Sub arcada temporo-zigomatică, la nivelul incizurii sigmoide."}],"correct":["B"],"pages":[555],"source":"set-2"},{"id":"set2-xXcS5NvW","fingerprint":"485d77488b9553f3","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele reprezintă accidente posibile în cazul anesteziei nervului alveolar inferior pe cale retromandibulară?","options":[{"id":"A","text":"Lezarea arterei maxilare interne."},{"id":"B","text":"Lezarea venei jugulare externe."},{"id":"C","text":"Lezarea arterei carotide externe."},{"id":"D","text":"Pareza tranzitorie a nervului facial."},{"id":"E","text":"Lezarea nervului lingual."}],"correct":["B","C","D"],"pages":[555],"source":"set-2"},{"id":"set2-_nqzDcgm","fingerprint":"beec886a0336f5cd","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce particularitate prezintă procedeul Veisbrem în ceea ce privește secvența de injectare a anestezicului?","options":[{"id":"A","text":"Se injectează inițial pentru nervul bucal, apoi se avansează cu acul pentru a anestezia nervii lingual și alveolar inferior."},{"id":"B","text":"Se utilizează două puncții separate, una pentru nervul bucal și una pentru nervii lingual și alveolar inferior."},{"id":"C","text":"Întreaga cantitate de anestezic se injectează într-un singur timp la contactul cu tuberozitatea mandibulară."},{"id":"D","text":"Se retrage acul 1-2 mm după contactul osos și se injectează întreaga cantitate de soluție, aspirând în prealabil."},{"id":"E","text":"Se depune o primă cantitate de anestezic la contactul osos pentru nervii lingual și alveolar inferior, apoi se retrage acul 3-4 mm și se injectează restul pentru nervul bucal."}],"correct":["E"],"pages":[555],"source":"set-2"},{"id":"set2-hE_z1QxR","fingerprint":"8212f9bc18120020","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următorii nervi sunt anesteziați prin procedeul Gow-Gates?","options":[{"id":"A","text":"Nervul bucal."},{"id":"B","text":"Nervul milohioidian."},{"id":"C","text":"Nervul facial."},{"id":"D","text":"Nervul auriculotemporal."},{"id":"E","text":"Nervul incisiv."}],"correct":["A","B","D","E"],"pages":[555],"source":"set-2"},{"id":"set2-5liQor25","fingerprint":"78a54c5e0ce5f96a","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Referitor la procedeul Gow-Gates, care este manevra obligatorie pentru a preveni puncția prea profundă și lezarea arterei maxilare interne?","options":[{"id":"A","text":"Pătrunderea acului la o adâncime de aproximativ 1,5 cm."},{"id":"B","text":"Menținerea cavității orale a pacientului în poziție semi-închisă."},{"id":"C","text":"Poziționarea corpului seringii în dreptul primului molar de partea opusă."},{"id":"D","text":"Retragerea acului 3-4 mm înainte de injectarea finală."},{"id":"E","text":"Obținerea contactului acului cu osul înainte de injectare."}],"correct":["E"],"pages":[555],"source":"set-2"},{"id":"set2-n3MDimNr","fingerprint":"e333c9ac979d45c1","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la căile de anestezie cutanată a nervului alveolar inferior sunt corecte?","options":[{"id":"A","text":"În calea retromandibulară, acul pătrunde 5,5-6,5 cm în profunzime."},{"id":"B","text":"Calea superioară are ca loc de puncție o zonă sub lobul urechii."},{"id":"C","text":"Sunt practicate în chirurgia oro-maxilo-facială când abordul oral nu este posibil."},{"id":"D","text":"Calea superioară este utilizată în caz de trismus accentuat."},{"id":"E","text":"Calea submandibulară este cea mai frecvent utilizată."}],"correct":["C","D","E"],"pages":[555],"source":"set-2"},{"id":"set2-kF5l378i","fingerprint":"4882de4fabd55e9d","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce definește tuberozitatea mandibulară, reper important în procedeul Veisbrem?","options":[{"id":"A","text":"O creastă osoasă care coboară de pe fața internă a apofizei coronoide până la nivelul planului de ocluzie."},{"id":"B","text":"Punctul de inserție a mușchiului pterigoidian extern pe fața internă a condilului."},{"id":"C","text":"O proeminență osoasă pe fața internă a ramului mandibular, la jumătatea distanței dintre incizura sigmoidă și spina Spix."},{"id":"D","text":"O proeminență osoasă localizată pe fața externă a condilului mandibular."},{"id":"E","text":"O depresiune osoasă situată medial și posterior de marginea posterioară a ramului ascendent."}],"correct":["C"],"pages":[555],"source":"set-2"},{"id":"set2-WswsQFTE","fingerprint":"362f4bfb911f811c","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este un avantaj major al procedeului Gow-Gates în comparație cu anestezia la spina Spix?","options":[{"id":"A","text":"Exclude complet riscul de pareză tranzitorie a nervilor cranieni oculomotori."},{"id":"B","text":"Timpul de instalare a anesteziei este semnificativ mai scurt."},{"id":"C","text":"Prezintă o rată ridicată de succes, de peste 75%, inclusiv în cazuri de inervație accesorie."},{"id":"D","text":"Necesită o cantitate mai mică de soluție anestezică pentru a obține un efect complet."},{"id":"E","text":"Distanța dintre trunchiul nervos și locul de depozitare a anestezicului este mai mică."}],"correct":["C"],"pages":[556],"source":"set-2"},{"id":"set2-hPWuZ4T6","fingerprint":"f35c832863f71cd8","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele reprezintă indicații pentru utilizarea procedeului de anestezie Vazirani-Akinosi?","options":[{"id":"A","text":"Deschiderea limitată a cavității orale."},{"id":"B","text":"Pacienți cu un proces zigomatic proeminent al maxilarului."},{"id":"C","text":"Imposibilitatea de a vizualiza reperele pentru anestezia nervului alveolar inferior."},{"id":"D","text":"Prezența unui canal mandibular bifid."},{"id":"E","text":"Necesitatea de a anestezia exclusiv nervul bucal."}],"correct":["A","C"],"pages":[556],"source":"set-2"},{"id":"set2-k5b73zAz","fingerprint":"af941425fc65cc74","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce nervi sunt anesteziați simultan prin procedeul Vazirani-Akinosi?","options":[{"id":"A","text":"Nervul alveolar inferior"},{"id":"B","text":"Nervul mentonier"},{"id":"C","text":"Nervul milohioidian"},{"id":"D","text":"Nervul bucal"},{"id":"E","text":"Nervul lingual"}],"correct":["A","B","C","E"],"pages":[556],"source":"set-2"},{"id":"set2-C_pf2IeU","fingerprint":"e8e60aad5c572222","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"În cadrul tehnicii Vazirani-Akinosi, care este orientarea acului de puncție și adâncimea de inserție în lipsa unui reper osos clar?","options":[{"id":"A","text":"Paralel cu planul de ocluzie superior, la o adâncime de aproximativ 2,5 cm."},{"id":"B","text":"Perpendicular pe planul de ocluzie superior, la o adâncime de 1,5 cm."},{"id":"C","text":"Paralel cu planul de ocluzie superior, la o adâncime de 5-10 mm."},{"id":"D","text":"Orientat spre condil, la jumătatea distanței față de gaura mandibulară, la o adâncime de 4 cm."},{"id":"E","text":"Tangent la ramul mandibular, până se obține contactul osos."}],"correct":["A"],"pages":[556],"source":"set-2"},{"id":"set2-NromoNjs","fingerprint":"d7d552917daa2824","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este secvența corectă a instalării anesteziei după infiltrarea soluției prin tehnica Vazirani-Akinosi?","options":[{"id":"A","text":"Deschiderea cavității orale, urmată de anestezia simultană a filetelor motorii și senzitive."},{"id":"B","text":"Anestezia mucoasei, apoi anestezia dinților și în final relaxarea musculară."},{"id":"C","text":"Anestezia filetelor senzitive, urmată de relaxarea musculaturii masticatorii."},{"id":"D","text":"Anestezia filetelor motorii, relaxarea musculaturii masticatorii, apoi anestezia filetelor senzitive."},{"id":"E","text":"Relaxarea simultană a musculaturii și anestezia filetelor senzitive."}],"correct":["D"],"pages":[556],"source":"set-2"},{"id":"set2-ohEOQmtc","fingerprint":"16f27445a8d8872c","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care dintre următoarele reprezintă un incident posibil în timpul aplicării tehnicii Vazirani-Akinosi?","options":[{"id":"A","text":"Lipsa contactului acului cu osul, ducând la eșecul anesteziei."},{"id":"B","text":"Lezarea directă a trunchiului nervos alveolar inferior."},{"id":"C","text":"Anestezia nervului bucal, necesitând intervenții suplimentare."},{"id":"D","text":"Injectarea accidentală a soluției anestezice în glanda parotidă."},{"id":"E","text":"Diplopie tranzitorie sau blefaroptoză."}],"correct":["D"],"pages":[556],"source":"set-2"},{"id":"set2-C0WZx_dU","fingerprint":"eaf0894b17516b4f","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce scop are anestezia nervului bucal și unde se realizează puncția anestezică?","options":[{"id":"A","text":"Este indicată în macroglosie; puncția se face pe fața internă a ramului mandibular."},{"id":"B","text":"Este o anestezie de completare pentru mucoasa gingivoalveolară distal de gaura mentonieră; puncția se face în vestibulul inferior, în dreptul premolarului doi."},{"id":"C","text":"Anesteziază simultan nervul lingual și milohioidian; puncția se face sublingual."},{"id":"D","text":"Este o anestezie de bază pentru toți molarii inferiori; puncția se face în trigonul retromolar."},{"id":"E","text":"Este o tehnică alternativă la Vazirani-Akinosi; puncția se face la nivelul joncțiunii muco-gingivale a molarilor superiori."}],"correct":["B"],"pages":[556],"source":"set-2"},{"id":"set2-aYhDJUoS","fingerprint":"6710fc5754f8802e","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt teritoriile anesteziate în urma unei anestezii separate a nervului lingual?","options":[{"id":"A","text":"Hemibuza inferioară și tegumentul regiunii mentoniere."},{"id":"B","text":"Regiunea postsulcală a hemilimbii de partea anesteziată."},{"id":"C","text":"Mucoasa hemiplanșeului bucal."},{"id":"D","text":"Versantul lingual al crestei alveolare de la ultimul molar la linia mediană."},{"id":"E","text":"Dinții frontali inferiori, de la canin la incisivul central."}],"correct":["B","C","D"],"pages":[557],"source":"set-2"},{"id":"set2-Ku1Cqdkm","fingerprint":"6b644932b207ee8c","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este direcția și profunzimea corectă a acului la realizarea puncției anestezice pentru nervul lingual în șanțul mandibulo-lingual, în dreptul ultimului molar?","options":[{"id":"A","text":"Înapoi și ușor înăuntru spre limbă, pătrunzând submucos 0,5 cm."},{"id":"B","text":"Înapoi și ușor în afară spre os, pătrunzând submucos aproximativ 1 cm."},{"id":"C","text":"Anterior și medial spre limbă, pătrunzând submucos 2 cm."},{"id":"D","text":"Strict perpendicular pe procesul alveolar, pătrunzând 1-2 mm."},{"id":"E","text":"În unghiul de răsfrângere a mucoasei, în dreptul caninului."}],"correct":["B"],"pages":[557],"source":"set-2"},{"id":"set2-1QvGbHlU","fingerprint":"712bbbd15622a2f1","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Pentru ce regiune specifică este indicată tehnica Dan Theodorescu de anestezie a nervului lingual?","options":[{"id":"A","text":"Întreaga hemilimbă și versantul lingual al crestei alveolare."},{"id":"B","text":"Regiunea posterioară a planșeului bucal, în apropierea spinei Spix."},{"id":"C","text":"Regiunea submandibulară, după ce nervul perforează mușchiul milohioidian."},{"id":"D","text":"Porțiunea anterioară a planșeului bucal, vizând filetele terminale ale nervului."},{"id":"E","text":"Anestezia trunchiului principal al nervului lingual la nivelul molarului de minte."}],"correct":["D"],"pages":[557],"source":"set-2"},{"id":"set2-1AXeFf2B","fingerprint":"41f35cb6191c6e72","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce nervi rezultă din bifurcația nervului alveolar inferior la nivelul găurii mentoniere și care este distribuția lor principală?","options":[{"id":"A","text":"Nervul incisiv (pentru părți moi) și nervul mentonier (porțiune intraosoasă)."},{"id":"B","text":"Nervul lingual (pentru limbă) și nervul bucal (pentru mucoasa obrazului)."},{"id":"C","text":"Doi nervi mentonieri, unul pentru hemibuză și unul pentru tegumentul regiunii mentoniere."},{"id":"D","text":"Nervul incisiv (porțiune terminală, intraosoasă) și nervul mentonier (iese prin gaură, pentru părți moi)."},{"id":"E","text":"Nervul alveolar inferior continuă ca un singur trunchi intraosos."}],"correct":["D"],"pages":[557],"source":"set-2"},{"id":"set2-Fy0U82-U","fingerprint":"1d755b8f184c94c4","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele structuri sunt anesteziate în cadrul anesteziei la gaura mentonieră?","options":[{"id":"A","text":"Hemibuza inferioară și tegumentul regiunii mentoniere."},{"id":"B","text":"Fibromucoasa vestibulară între gaura mentonieră și linia mediană."},{"id":"C","text":"Mucoasa hemiplanșeului bucal."},{"id":"D","text":"Dinții frontali inferiori de partea anesteziată (canin, incisivi)."},{"id":"E","text":"Molarii inferiori și premolarul doi."}],"correct":["A","B","D"],"pages":[557],"source":"set-2"},{"id":"set2-KR7jwDVA","fingerprint":"08145662e96e1543","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt indicațiile pentru anestezia la gaura mentonieră?","options":[{"id":"A","text":"Completarea anesteziei nervului alveolar inferior pentru proceduri la nivelul liniei mediene."},{"id":"B","text":"Intervenții chirurgicale labio-mentoniere unde infiltrația locală ar deforma regiunea."},{"id":"C","text":"Anestezia de elecție pentru extracția molarilor de minte inferiori."},{"id":"D","text":"Proceduri chirurgicale extinse asupra limbii și planșeului bucal."},{"id":"E","text":"Tratamentul afecțiunilor pulpare la toți dinții mandibulari de pe o hemiarcadă."}],"correct":["A","B"],"pages":[557],"source":"set-2"},{"id":"set2-A0E3CikU","fingerprint":"1dcd9399139e7ebe","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele repere anatomice sunt corecte pentru localizarea găurii mentoniere la un pacient dentat?","options":[{"id":"A","text":"La 28 mm distanță de linia mediană."},{"id":"B","text":"La 14-15 mm de marginea bazilară a mandibulei."},{"id":"C","text":"Inferior de linia care unește apexurile celor doi premolari inferiori."},{"id":"D","text":"Foarte aproape de creasta alveolară, sub mucoasa gingivală."},{"id":"E","text":"La mijlocul distanței dintre simfiza mentonieră și marginea anterioară a mușchiului maseter."}],"correct":["A","B","C"],"pages":[557],"source":"set-2"},{"id":"set2-9V4Ry4tD","fingerprint":"ee3ec5f323b760d6","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"În cazul anesteziei superficiale a nervului lingual la nivelul planșeului bucal în dreptul molarului de minte, care sunt parametrii corecți ai procedurii?","options":[{"id":"A","text":"Pătrundere submucos 1 cm, depunere de 1,5 ml anestezic și instalare imediată."},{"id":"B","text":"Pătrundere submucos 1-2 mm, depunere de 0,5-0,8 ml anestezic și instalare în 1-2 minute."},{"id":"C","text":"Pătrundere submucos 1-2 mm, depunere de 2 ml anestezic și instalare în 3-5 minute."},{"id":"D","text":"Pătrundere supraperiostală, depunere de 0,2 ml anestezic și instalare în 5 minute."},{"id":"E","text":"Pătrundere până la contactul osos, depunere de 1 ml anestezic și instalare în 30 de secunde."}],"correct":["B"],"pages":[557],"source":"set-2"},{"id":"set2-KxjaydyH","fingerprint":"e79b0011b5441370","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este rolul uzual al anesteziei singulare a nervului bucal în practica stomatologică?","options":[{"id":"A","text":"Este o tehnică de sine stătătoare, nefiind justificată în combinație cu alte anestezii."},{"id":"B","text":"Se realizează întotdeauna pe cale cutanată pentru a evita lezarea nervului lingual."},{"id":"C","text":"Este tehnica de elecție pentru intervențiile pe planșeul bucal."},{"id":"D","text":"Este o anestezie de completare în cadrul procedeului clasic de anestezie la spina Spix."},{"id":"E","text":"A înlocuit complet anestezia nervului lingual în chirurgia modernă."}],"correct":["D"],"pages":[557],"source":"set-2"},{"id":"set2-gTkyeJRg","fingerprint":"35ae1b322b4e9bb2","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt caracteristicile puncției anestezice pe cale orală pentru nervul mentonier?","options":[{"id":"A","text":"Injectarea soluției anestezice strict la nivelul găurii mentoniere produce anestezia dinților și a procesului alveolar."},{"id":"B","text":"Cantitatea de soluție anestezică injectată este de 2-3 ml."},{"id":"C","text":"Acul formează un unghi de 15-20° cu axul premolarului doi."},{"id":"D","text":"Direcția de inserție a acului este oblică în sus, înapoi și în afară."},{"id":"E","text":"Puncția se efectuează în vestibulul inferior, în mucoasa mobilă, la nivelul rădăcinii meziale a primului molar."}],"correct":["C","E"],"pages":[558],"source":"set-2"},{"id":"set2-lmrqhsLR","fingerprint":"2c77260279e8cb2d","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce element clinic indică o angajare reușită a acului în canalul mentonier în timpul anesteziei pe cale orală?","options":[{"id":"A","text":"Necesitatea injectării unei cantități de 2 ml de anestezic pentru a obține efectul."},{"id":"B","text":"Pacientul simte o durere surdă la nivelul molarilor."},{"id":"C","text":"Acul devine mobil după traversarea mucoasei, permițând tatonarea planului osos."},{"id":"D","text":"Acul devine fix, iar pacientul raportează o senzație de fulgurație în dinții incisivi."},{"id":"E","text":"Anestezia imediată a părților moi din regiunea mentonieră."}],"correct":["D"],"pages":[558],"source":"set-2"},{"id":"set2-mQHJUtBu","fingerprint":"7ac0307121ab1537","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt indicațiile și reperele pentru anestezia nervului mentonier pe cale cutanată?","options":[{"id":"A","text":"Puncția se realizează sub și înapoia găurii mentoniere."},{"id":"B","text":"Acul se introduce în jos, înăuntru și înainte, până la contactul cu planul osos."},{"id":"C","text":"După pătrunderea în gaura mentonieră, acul se avansează 2,5 cm."},{"id":"D","text":"Este frecvent utilizată pentru tratamentul nevralgiei trigeminale cu zonă „trigger” la nivelul găurii mentoniere."},{"id":"E","text":"Puncția se efectuează la aproximativ 2 cm înapoia comisurii bucale."}],"correct":["B","D","E"],"pages":[558],"source":"set-2"},{"id":"set2-f2gArhTU","fingerprint":"278cf378536d295a","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"În ce situație clinică este indicată în mod specific anestezia nervului maseterin?","options":[{"id":"A","text":"Intervenții chirurgicale pe procesul alveolar."},{"id":"B","text":"Anestezia dinților incisivi."},{"id":"C","text":"Anestezia părților moi din regiunea geniană."},{"id":"D","text":"Nevralgia de trigemen."},{"id":"E","text":"Prezența trismusului."}],"correct":["E"],"pages":[558],"source":"set-2"},{"id":"set2-DkxP7hQw","fingerprint":"0530cf8ece763178","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care afirmații descriu corect procedura de anestezie a nervului maseterin?","options":[{"id":"A","text":"Prin avansarea acului cu încă 1 cm de la profunzimea inițială, se anesteziază și mușchiul temporal."},{"id":"B","text":"Puncția se practică sub arcada zigomatică, imediat înaintea tuberculului zigomatic anterior."},{"id":"C","text":"Se injectează o cantitate de 2-3 ml de soluție anestezică după atingerea mușchiului maseter la o profunzime de 2,5 cm."},{"id":"D","text":"La o profunzime de 2,5 cm, se pot anestezia mușchiul maseter, mușchiul temporal și mușchii pterigoidieni."},{"id":"E","text":"Nervul maseterin este un nerv senzitiv abordat la incizura sigmoidă."}],"correct":["A","B","C"],"pages":[558],"source":"set-2"},{"id":"set2-3c7yCCgh","fingerprint":"2d490e2fd2700dc4","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt indicațiile clinice pentru utilizarea anesteziei de contact?","options":[{"id":"A","text":"Suprimarea reflexului de vomă în cazul aplicării filmului radiologic distal în cavitatea orală."},{"id":"B","text":"Extracția dinților permanenți cu mobilitate de gradul I."},{"id":"C","text":"Adaptarea unei coroane la colet și finisarea unei obturații de colet pe fibromucoasa gingivală."},{"id":"D","text":"Incizia abceselor profunde situate subperiostal."},{"id":"E","text":"Realizarea anesteziei prealabile înaintea puncției anestezice pe fibromucoasa gingivală."}],"correct":["A","C","E"],"pages":[545],"source":"set-2"},{"id":"set2-D7ulMuZ0","fingerprint":"76b5130ddc88de3b","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Pentru care dintre următoarele structuri nervoase anestezia topică utilizează tehnica de „imbibiție” cunoscută sub denumirea de procedeul Escat?","options":[{"id":"A","text":"Nervul infraorbital la nivelul planșeului fosei nazale, posterior de cornetul mijlociu."},{"id":"B","text":"Nervul nazopalatin al lui Scarpa pe podeaua fosei nazale, anterior de cornetul inferior."},{"id":"C","text":"Nervul palatin mare pe bolta palatină, adiacent molarului de minte."},{"id":"D","text":"Nervul alveolar inferior la nivelul foramenului mandibular."},{"id":"E","text":"Nervul lingual în șanțul mandibulo-lingual, în dreptul molarului de minte."}],"correct":["B"],"pages":[545],"source":"set-2"},{"id":"set2-4PBeJHlC","fingerprint":"8ae035c7941d238d","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce forme de anestezie sunt considerate anestezii prin infiltrație specifice stomatologiei și chirurgiei oro-maxilo-faciale la nivelul cavității orale?","options":[{"id":"A","text":"Anestezia paraapicală supra-periostală."},{"id":"B","text":"Anestezia intraligamentară și intrapulpară."},{"id":"C","text":"Anestezia intraosoasă, cu varianta intraseptală."},{"id":"D","text":"Anestezia topică prin imbibiție."},{"id":"E","text":"Anestezia tronculară periferică."}],"correct":["A","B","C","E"],"pages":[545],"source":"set-2"},{"id":"set2-aiszw_eF","fingerprint":"7a3f5ee52f166b73","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este consecința directă a limitărilor anesteziei submucoase în incizia abceselor superficializate?","options":[{"id":"A","text":"Ischemia mucoasei impune întârzierea inciziei pentru a preveni necroza țesuturilor superficiale."},{"id":"B","text":"Mucoasa capătă un aspect ischemic pronunțat de lungă durată, permițând incizii laborioase."},{"id":"C","text":"Incizia necesită o perioadă lungă de așteptare pentru ca anestezicul să difuzeze dincolo de periost."},{"id":"D","text":"Senzația dureroasă apare la exercitarea presiunii asupra periostului deoarece acesta nu este anesteziat."},{"id":"E","text":"Anestezicul pătrunde profund în structurile osoase, generând un blocaj nervos complet pe traiectul viitoarei incizii."}],"correct":["D"],"pages":[545],"source":"set-2"},{"id":"set2-5wTsKEXK","fingerprint":"4080f04d85d1f4ce","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt particularitățile preparatelor și etapelor de lucru în anestezia topică?","options":[{"id":"A","text":"Anestezia topică asigură insensibilitatea stratului superficial al mucoasei și a țesutului submucos pe o adâncime de 10-15 milimetri."},{"id":"B","text":"Produsele sub formă de aerosoli oferă o precizie superioară pastelor în dozarea cantității de anestezic folosit."},{"id":"C","text":"Tehnica de utilizare presupune uscarea prealabilă a locului de aplicare a anestezicului înaintea depunerii acestuia."},{"id":"D","text":"Concentrația anestezicului topic folosit este inferioară celei destinate injectării."},{"id":"E","text":"Instalarea anesteziei necesită un timp de așteptare de 2-3 până la 10-15 minute, iar efectul persistă de la 10-15 minute, putând ajunge uneori la 45-60 minute."}],"correct":["C","E"],"pages":[545],"source":"set-2"},{"id":"set2-F_pFM4ao","fingerprint":"ac568c1727b0bbf5","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt particularitățile anesteziei subcutanate „în baraj”?","options":[{"id":"A","text":"Acul pătrunde subcutanat strict în patru puncte corespunzătoare vârfurilor patrulaterului vizat."},{"id":"B","text":"Printr-o singură puncție și rotarea acului la 45°, se realizează concomitent două laturi ale patrulaterului."},{"id":"C","text":"Anestezia se obține prin infiltrarea directă, strat cu strat, a ariei viitoarei plăgi operatorii."},{"id":"D","text":"Tehnica este indicată în intervențiile de la nivel tegumentar pentru excizia formațiunilor de mici dimensiuni."},{"id":"E","text":"Infiltrația se realizează la distanță de leziune, creându-se o arie care circumscrie viitoarea plagă."}],"correct":["B","D","E"],"pages":[546],"source":"set-2"},{"id":"set2-RCtvw6qC","fingerprint":"d893f0d34b18817d","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este un factor limitant anatomic specific pentru difuzarea optimă a soluției anestezice în anestezia paraapicală supraperiostală la nivelul maxilarului?","options":[{"id":"A","text":"Densitatea crescută a spongiei și lipsa canalelor haversiene în regiunea incisivilor centrali superiori."},{"id":"B","text":"Structura osoasă a crestei zigomatico-alveolare situată în dreptul molarului de șase ani."},{"id":"C","text":"Aderența fermă a mucoasei deasupra apexului dinților laterali care previne injectarea."},{"id":"D","text":"Prezența unei corticale osoase foarte subțiri la nivelul întregii arcade superioare."},{"id":"E","text":"Lărgimea excesivă a canalelor haversiene din structura osoasă a pacienților tineri."}],"correct":["B"],"pages":[546],"source":"set-2"},{"id":"set2-5swT1xVR","fingerprint":"9a19ae7afc003bbe","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt indicațiile și contraindicațiile tehnicii de anestezie paraapicală supraperiostală?","options":[{"id":"A","text":"Este contraindicată categoric la pacienții care prezintă tumori benigne sau maligne la nivelul zonei de puncție."},{"id":"B","text":"Este contraindicată în prezența afecțiunilor de tip supurativ la locul de puncție din cauza riscului de diseminare."},{"id":"C","text":"Este evitată la pacienții tineri din cauza corticalei osoase mai puțin dense ce favorizează rezorbția rapidă."},{"id":"D","text":"Este indicată de rutină pentru inserarea implanturilor dentare, rezecții apicale și intervenții parodontale."},{"id":"E","text":"Este eficientă și indicată pe toată întinderea arcadei mandibulare, datorită spongiei bogate."}],"correct":["A","B","D"],"pages":[546],"source":"set-2"},{"id":"set2-3vOYLTGa","fingerprint":"8fe293d9f304b83c","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce aspecte caracterizează efectuarea puncției anestezice în tehnica paraapicală supraperiostală?","options":[{"id":"A","text":"Puncția se realizează în mucoasa mobilă din vestibulul bucal, deasupra apexului dentar."},{"id":"B","text":"Cantitatea de anestezic injectată în mod frecvent pentru obținerea efectului este de 1,5- 1,7 ml."},{"id":"C","text":"Pentru anestezia incisivilor centrali superiori, se practică abordul din partea opusă, traversând frenul buzei superioare."},{"id":"D","text":"Acul avansează având bizoul orientat exclusiv înspre mucoasa vestibulară mobilă."},{"id":"E","text":"Retragerea acului impune depunerea soluției strict în porțiunea distală a zonei anesteziate."}],"correct":["A","B","C"],"pages":[546],"source":"set-2"},{"id":"set2-BNc_I4lF","fingerprint":"80f14df470e8ed6c","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este mecanismul fiziologic și anatomic prin care se instalează efectul anesteziei paraapicale supraperiostale?","options":[{"id":"A","text":"Substanța anestezică blochează trunchiurile nervoase mari înainte de diviziunea lor în plexul dentar superior."},{"id":"B","text":"Anestezicul acționează strict la nivelul mucoasei vestibulare și al periostului, fără capacitatea de a inactiva terminațiile dentare pulpare."},{"id":"C","text":"Mecanismul se bazează pe infiltrarea circumferențială la nivelul coletului dentar și migrarea anestezicului prin ligamentul parodontal."},{"id":"D","text":"Injectarea soluției anestezice se face direct intraosos, urmată de difuzarea prin corticală spre exterior."},{"id":"E","text":"Substanța anestezică este depusă supraperiostal și pătrunde prin canalele haversiene pentru a anestezia ramurile dentare înainte de intrarea în apex."}],"correct":["E"],"pages":[546],"source":"set-2"},{"id":"set2-8b15ZCN9","fingerprint":"910a352bc067e74f","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele reprezintă avantaje ale anesteziei intraligamentare?","options":[{"id":"A","text":"Scăderea frecvenței apariției alveolitei postextracționale comparativ cu alte tehnici anestezice."},{"id":"B","text":"Instalarea anesteziei într-un interval scurt de timp, cuprins între 25 și 40 de secunde."},{"id":"C","text":"Posibilitatea de a anestezia simultan mai mulți dinți fără a atinge doza toxică a anestezicului."},{"id":"D","text":"Anestezierea extinsă a părților moi de vecinătate, utilă în intervențiile parodontale ample."},{"id":"E","text":"Necesitatea utilizării unei cantități reduse de substanță anestezică, de regulă 0,15-0,20 ml."}],"correct":["B","C","E"],"pages":[546],"source":"set-2"},{"id":"set2-BB3_Afwv","fingerprint":"8637fdf8d4762b83","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următorii factori sunt responsabili pentru apariția complicațiilor locale specifice anesteziei intraligamentare, cum ar fi durerea și alveolita postextracțională?","options":[{"id":"A","text":"Utilizarea substanțelor anestezice lipsite de vasoconstrictor."},{"id":"B","text":"Injectarea prea rapidă a soluției anestezice, care produce edem local și extruzia ușoară a dintelui."},{"id":"C","text":"Orientarea incorectă a bizoului acului către papila dentară în timpul puncției."},{"id":"D","text":"Utilizarea incorectă a seringii speciale de presiune."},{"id":"E","text":"Injectarea unui volum excesiv de anestezic local în spațiul parodontal."}],"correct":["B","D","E"],"pages":[547],"source":"set-2"},{"id":"set2-F-gn7gMR","fingerprint":"cc76ab9662bb529b","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt afirmațiile exacte privind indicațiile și contraindicațiile anesteziei intraligamentare?","options":[{"id":"A","text":"Se recomandă pacienților cu tulburări hepatice pentru a evita puncțiile profunde."},{"id":"B","text":"Este recomandată pacienților aflați sub tratament cu medicamente anticoagulante."},{"id":"C","text":"Este contraindicată la pacienții hemofilici din cauza riscului de sângerare masivă în spațiul parodontal."},{"id":"D","text":"Prezența infecțiilor la locul de puncție reprezintă o contraindicație pentru acest tip de anestezie."},{"id":"E","text":"Este indicată de elecție în cazul dinților temporari, datorită volumului mic de anestezic necesar."}],"correct":["A","B","D"],"pages":[547],"source":"set-2"},{"id":"set2-EwTApcmo","fingerprint":"2d4de308403022e8","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt enunțurile exacte referitoare la dozele maxime de soluție anestezică recomandate în anestezia intraligamentară la pacientul adult?","options":[{"id":"A","text":"Pentru articaină 4% cu adrenalină 1:100.000, doza este de 0,9 ml pentru orice dinte la care se practică două puncții."},{"id":"B","text":"Pentru articaină 4% cu adrenalină 1:100.000, doza este de 0,45 ml pentru orice dinte la care se practică două puncții."},{"id":"C","text":"Pentru xilină 2% cu adrenalină 1:100.000, doza este de 0,9 ml pentru o singură puncție la un incisiv mandibular."},{"id":"D","text":"Pentru ambele tipuri de anestezic, dozele necesare pentru un incisiv mandibular sunt identice."},{"id":"E","text":"Pentru xilină 2% cu adrenalină 1:100.000, doza este de 1,8 ml pentru toți dinții la care sunt necesare două puncții anestezice."}],"correct":["A","C","E"],"pages":[547],"source":"set-2"},{"id":"set2-Aq4ISQq6","fingerprint":"65dcf642b078fbc3","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele enunțuri descriu în mod adecvat tehnica de realizare și mecanismul de difuziune a substanței în anestezia intraligamentară?","options":[{"id":"A","text":"Anestezicul difuzează prin osul cortical și spongios până ajunge la pachetul vasculo-nervos apical."},{"id":"B","text":"La dinții pluriradiculari, anestezia intraligamentară presupune efectuarea exclusivă de puncții vestibulare."},{"id":"C","text":"O apăsare pe declanșatorul seringii speciale eliberează o cantitate prestabilită de 0,20 ml de anestezic."},{"id":"D","text":"Seringile mecanice creează un gradient de presiune care favorizează difuziunea anestezicului de la apex spre zona coronară a dintelui."},{"id":"E","text":"Acul se introduce prin papila dentară cu bizoul orientat spre mucoasa vestibulară."}],"correct":["A","C"],"pages":[547],"source":"set-2"},{"id":"set2-0yQ4zhmk","fingerprint":"5d4fd3fd3814071c","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la sistemul de injectare intraligamentară controlat computerizat (STA Wand)?","options":[{"id":"A","text":"Feedbackul sonor este alcătuit din tonuri descendente ce măsoară presiunea."},{"id":"B","text":"Culoarea galbenă a sistemului indică o presiune minimă la vârful acului."},{"id":"C","text":"Culoarea verde a scării vizuale indică o presiune mare la nivelul spațiului parodontal."},{"id":"D","text":"Dispozitivul poate fi utilizat la dinții temporari fără a afecta dezvoltarea dintelui permanent."},{"id":"E","text":"Culoarea roșie a ledurilor indică o presiune mare la nivelul spațiului parodontal."}],"correct":["C","D"],"pages":[548],"source":"set-2"},{"id":"set2-RSmBUbU8","fingerprint":"1bf6f1a20a4751b7","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce caracteristici prezintă sistemul X-Tip utilizat în anestezia intraosoasă?","options":[{"id":"A","text":"Se indică utilizarea unui corectiv vasoconstrictor cu concentrația de 1:200.000, din cauza vascularizației zonei."},{"id":"B","text":"Injectarea substanței anestezice se realizează cu un ac care are un calibru dublu comparativ cu cel al frezei."},{"id":"C","text":"Sistemul este format dintr-o freză și o componentă de ghidaj care se separă după perforarea corticalei."},{"id":"D","text":"Componenta de ghidaj este îndepărtată anterior injectării soluției anestezice."},{"id":"E","text":"Pentru tratamentul limitat la unul sau doi dinți se recomandă administrarea a aproximativ 0,5 ml de soluție anestezică."}],"correct":["A","C","E"],"pages":[548],"source":"set-2"},{"id":"set2-LZ0POiEs","fingerprint":"5211b6162e779949","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt aspectele legate de complicațiile și riscurile asociate anesteziei intraosoase?","options":[{"id":"A","text":"Tehnica prezintă un risc de injectare intravasculară ridicat, ce depășește frecvent 20%."},{"id":"B","text":"Injectarea anestezicului la nivelul orificiului mentonier se asociază cu un risc crescut de fenomene disestezice."},{"id":"C","text":"Utilizarea intempestivă a piesei de mână sub presiune necontrolată determină necroză osoasă superficială și formarea unui orificiu fistulos."},{"id":"D","text":"Disconfortul algic post-anestezic poate apărea în 5% dintre cazuri și cedează la administrarea de analgetice uzuale."},{"id":"E","text":"Un dezavantaj frecvent este anestezierea persistentă a părților moi, în special a mucoasei labiale și a limbii."}],"correct":["B","C","D"],"pages":[548],"source":"set-2"},{"id":"set2-lUonKypX","fingerprint":"527124593442c5e8","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele caracteristici descriu tehnica și parametrii de execuție ai anesteziei intraseptale?","options":[{"id":"A","text":"Durata medie a anesteziei intraseptale este de peste 45 de minute, fiind una dintre tehnicile de lungă durată."},{"id":"B","text":"Pentru infiltrarea profundă în septul interdentar se depozitează lent, în 20 de secunde, o cantitate de 0,4 ml de anestezic."},{"id":"C","text":"Puncționarea papilei interdentare se execută la o distanță de 2 mm deasupra vârfului ei."},{"id":"D","text":"Acul se poziționează la 45 de grade față de axul lung al dintelui și la 90 de grade față de țesutul moale."},{"id":"E","text":"Metoda este contraindicată în prezența proceselor infecțioase sau a inflamației severe la locul puncției."}],"correct":["B","D","E"],"pages":[549],"source":"set-2"},{"id":"set2-3FxwCR-f","fingerprint":"2f9663c966a3fe81","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Prin ce caracteristici și etape se distinge anestezia intrapulpară?","options":[{"id":"A","text":"Prezintă riscul crescut de injectare intravasculară din cauza vascularizației abundente a pulpei dentare."},{"id":"B","text":"Pentru obținerea unui efect optim, se injectează o cantitate de 2-3 ml de soluție anestezică, lent, pe parcursul a două minute."},{"id":"C","text":"Instalarea se produce rapid, în aproximativ 30 de secunde, având o durată de acțiune relativ scurtă, de 15-20 de minute."},{"id":"D","text":"Asigură controlul durerii doar prin efectul farmacologic, presiunea de injectare neavând un rol terapeutic."},{"id":"E","text":"Inserția acului și injectarea soluției generează o scurtă perioadă de sensibilitate dureroasă care permite ulterior instrumentarea mecanică."}],"correct":["C","E"],"pages":[550],"source":"set-2"},{"id":"set2--DLxgR0k","fingerprint":"ae23187bf919e95e","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care dintre următoarele reprezintă o caracteristică a teritoriului anesteziat prin tehnica la tuberozitate?","options":[{"id":"A","text":"Anestezia se poate instala uneori, parțial sau total, în zona premolarilor."},{"id":"B","text":"Anesteziază constant ramul mandibular al nervului trigemen."},{"id":"C","text":"Cuprinde peretele anterior al sinusului maxilar și mucoasa sinusală adiacentă."},{"id":"D","text":"Cuprinde fibromucoasa palatină a molarilor superiori."},{"id":"E","text":"Este întotdeauna eficientă pentru rădăcina mezio-vestibulară a molarului de 6 ani."}],"correct":["A"],"pages":[550],"source":"set-2"},{"id":"set2-jMIh33sn","fingerprint":"320d892ba6af1bfc","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt afirmațiile adevărate privind contraindicațiile și complicațiile anesteziei la tuberozitate?","options":[{"id":"A","text":"Este contraindicată la pacienții aflați sub tratament cu anticoagulante."},{"id":"B","text":"Hematomul se formează în urma hemoragiei apărute prin înțeparea cu acul a arterei maxilare."},{"id":"C","text":"Tratamentul de urgență al hematomului implică aplicarea de presiune pe obraz asociată cu o compresiune orală."},{"id":"D","text":"Hematomul are o evoluție lentă, limitată strict de structurile osoase ale spațiului pterigo-maxilar."},{"id":"E","text":"Este contraindicată în prezența proceselor inflamatorii din treimea distală a vestibulului superior."}],"correct":["A","C","E"],"pages":[550],"source":"set-2"},{"id":"set2-A_h3UQk5","fingerprint":"53c4dba0d1e2fedd","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Referitor la tehnica de realizare a anesteziei la tuberozitate pe cale orală, care dintre următoarele aspecte sunt adevărate?","options":[{"id":"A","text":"Locul de puncție se situează în mucoasa mobilă, deasupra rădăcinii meziale a molarului de 12 ani."},{"id":"B","text":"Acul pătrunde de-a lungul tuberozității menținându-se contactul osos până la o profunzime de 2-2,5 cm."},{"id":"C","text":"Mandibula trebuie deviată de partea opusă locului de puncție pentru a nu bloca accesul coronoidelor."},{"id":"D","text":"Reperele folosite includ creasta zigomato-alveolară și rădăcina mezială a molarului de 12 ani."},{"id":"E","text":"Direcția acului formează un unghi de 90° cu planul de ocluzie al molarilor superiori."}],"correct":["A","B","D"],"pages":[551],"source":"set-2"},{"id":"set2-jxi0iIEd","fingerprint":"8faa321e35f72106","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Când este indicată abordarea cutanată (externă) pentru anestezia la tuberozitate?","options":[{"id":"A","text":"Când afecțiunile asociate statusului general contraindică anestezia generală și există obstacole la locul de puncție pe cale orală."},{"id":"B","text":"Atunci când se dorește evitarea producerii anesteziei simultane a ramului mandibular al nervului trigemen."},{"id":"C","text":"La pacienții cu risc hemoragic ridicat, pentru a preveni înțeparea plexului venos pterigoidian."},{"id":"D","text":"Când anestezia plexală este ineficientă pentru intervențiile la nivelul molarilor de minte."},{"id":"E","text":"Ca procedeu de primă intenție în chirurgia oro-maxilo-facială actuală pentru a reduce riscul de formare a hematoamelor."}],"correct":["A"],"pages":[551],"source":"set-2"},{"id":"set2-iKn0rjH5","fingerprint":"02184e4d7afc45d5","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este motivul anatomic care justifică injectarea soluției anestezice în mod progresiv și continuu în timpul tehnicii anesteziei la tuberozitate?","options":[{"id":"A","text":"Limitarea difuziei soluției anestezice strict la nivelul peretelui posterior al sinusului maxilar."},{"id":"B","text":"Prevenirea distensiei bruște a fibromucoasei vestibulare și a ischemiei locale."},{"id":"C","text":"Administrarea lentă impusă de cantitatea mare de anestezic, ce depășește frecvent 3 ml."},{"id":"D","text":"Pătrunderea la nivele diferite în os a filetelor nervilor alveolari supero-posteriori."},{"id":"E","text":"Evitarea difuzării substanței spre ramul mandibular al nervului trigemen, situat medial."}],"correct":["D"],"pages":[551],"source":"set-2"},{"id":"set2-XsRL2o8x","fingerprint":"1e54ea126d24c1be","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la inervația palatinală și anestezia nervului nazopalatin sunt corecte?","options":[{"id":"A","text":"Limita posterioară a zonei anesteziate prin abordul la gaura incisivă este reprezentată de o linie transversală de la canin la canin."},{"id":"B","text":"Teritoriul anesteziat de nervul nazopalatin cuprinde treimea anterioară a fibromucoasei palatine."},{"id":"C","text":"Puncția anestezică pe cale orală se face introducând acul strict pe linia mediană, direct prin centrul papilei incisive."},{"id":"D","text":"Procedeul Escat reprezintă o metodă alternativă de anestezie prin puncție la nivelul mucoasei nazale."},{"id":"E","text":"Mucoasa palatinală din dreptul caninului superior este inervată atât de nervul nazopalatin, cât și de nervul palatin mare."}],"correct":["A","B","E"],"pages":[551],"source":"set-2"},{"id":"set2-Bbnv5QnH","fingerprint":"c310b528e0c87084","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"În vederea realizării anesteziei nervului palatin mare (la gaura palatină posterioară), ce repere anatomice și detalii tehnice sunt indicate?","options":[{"id":"A","text":"Gaura palatină este situată la aproximativ 1 cm înaintea cârligului aripii interne a apofizei pterigoide."},{"id":"B","text":"Puncția anestezică se realizează în șanțul palatin, frecvent în dreptul molarului doi, unde mucoasa prezintă o înfundare."},{"id":"C","text":"Este esențială pătrunderea cu acul profund în canalul palatin pentru o anestezie eficientă a celor două treimi posterioare ale bolții."},{"id":"D","text":"Acul trebuie orientat cu o direcție în sus, înainte și ușor în afară, cu seringa la comisura de aceeași parte."},{"id":"E","text":"Unul dintre repere plasează locul injecției la 0,5 cm înaintea marginii posterioare a palatului dur."}],"correct":["A","B","E"],"pages":[552],"source":"set-2"},{"id":"set2-0ZPKpvDy","fingerprint":"9e14b983a6ed8190","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt accidentele și complicațiile posibile, precum și factorii de risc asociați anesteziei la nivelul fibromucoasei palatine posterioare și anesteziei prin infiltrație?","options":[{"id":"A","text":"Pătrunderea acului excesiv de mult către anterior în anestezia nervului palatin mare determină infiltrarea vălului moale și producerea unui edem tranzitoriu."},{"id":"B","text":"Hemoragia rezultată din înțeparea vaselor palatine constituie o complicație majoră ce se tratează exclusiv prin sutură hemostatică."},{"id":"C","text":"Puncția anestezică prin infiltrație pentru o arie redusă necesită orientarea acului oblic față de planul osos, la 0,5 cm de marginea gingivală."},{"id":"D","text":"Injectarea bruscă a unei cantități mari de substanță anestezică duce la distensia și decolarea mucoperiostului, generând un risc de necroză a fibromucoasei."},{"id":"E","text":"Aderența crescută a fibromucoasei palatine față de planul osos reprezintă un factor favorizant pentru necroza de mucoasă în caz de injectare intempestivă."}],"correct":["D","E"],"pages":[552],"source":"set-2"},{"id":"set2-0pGtuJ7b","fingerprint":"6d5630948c5a0d45","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Referitor la tehnica de anestezie a nervului nazopalatin și modificările aduse pentru reducerea durerii, care enunțuri sunt adevărate?","options":[{"id":"A","text":"Abordul Malamed presupune o pătrundere perpendiculară printre incisivi spre papila interincisivă, pornind de pe creasta vestibulară la baza frenului labial."},{"id":"B","text":"Tehnica clasică presupune obligativitatea anesteziei de contact și puncția strict pe marginea papilei incisive pentru a diminua durerea."},{"id":"C","text":"Tehnica modificată de Malamed inițiază insensibilizarea printr-o puncție la nivelul frenului labial superior."},{"id":"D","text":"În lipsa instalării complete a anesteziei după infiltrarea printre incisivi, se practică direct incizia fără puncții suplimentare."},{"id":"E","text":"Procedeul Escat produce anestezia nervului nazopalatin pe podeaua fosei nazale prin intermediul unei puncții profunde."}],"correct":["A","B","C"],"pages":[552],"source":"set-2"},{"id":"set2-3AXuq0DO","fingerprint":"2986d533120b1e78","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este cantitatea de soluție anestezică și profunzimea de pătrundere recomandate în tehnica uzuală pe cale orală pentru anestezia nervului nazopalatin la gaura incisivă?","options":[{"id":"A","text":"Pătrundere de 1 cm în canal, injectând 1,0 - 1,5 ml anestezic."},{"id":"B","text":"Pătrundere de 0,5 cm în canal, injectând 0,5 - 1,0 ml anestezic."},{"id":"C","text":"Pătrundere la nivelul osului fără intrare în canal, injectând 0,3 - 0,5 ml anestezic."},{"id":"D","text":"Pătrundere de 1,5 cm în canal, injectând 0,2 - 0,3 ml anestezic."},{"id":"E","text":"Pătrundere de 0,5 cm în canal, injectând 0,2 - 0,5 ml anestezic."}],"correct":["E"],"pages":[552],"source":"set-2"},{"id":"set2-ft2LqKhj","fingerprint":"6a6f71a8832855e6","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt structurile anatomice cuprinse în aria de anestezie a nervului infraorbital?","options":[{"id":"A","text":"Aripa nasului."},{"id":"B","text":"Mucoasa palatină din regiunea frontală superioară."},{"id":"C","text":"Pleoapa inferioară."},{"id":"D","text":"Jumătate din buza inferioară."},{"id":"E","text":"Peretele anterior al sinusului maxilar și mucoasa care îl tapetează."}],"correct":["A","C","E"],"pages":[553],"source":"set-2"},{"id":"set2-iUBi83-E","fingerprint":"7c6241c314d65da9","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt reperele anatomice care descriu localizarea corectă a găurii infraorbitale?","options":[{"id":"A","text":"Pe linia verticală care trece între cei doi premolari superiori."},{"id":"B","text":"Deasupra suturii zigomato-maxilare."},{"id":"C","text":"La 6 - 8 mm sub rebordul orbitar inferior."},{"id":"D","text":"La unirea treimii externe cu cele două treimi interne ale marginii infraorbitale."},{"id":"E","text":"La 5 mm înăuntrul liniei verticale mediopupilare."}],"correct":["A","C","E"],"pages":[553],"source":"set-2"},{"id":"set2-sb3AqHhs","fingerprint":"9a8b55abb5fa4e84","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce complicații pot apărea ca urmare a pătrunderii acului în orbită în timpul puncției anestezice pe cale cutanată a nervului infraorbital?","options":[{"id":"A","text":"Diplopie tranzitorie prin anestezia ramurii inferioare a nervului oculomotor comun."},{"id":"B","text":"Lipsă temporară a vederii prin anestezia nervului optic."},{"id":"C","text":"Lipsa definitivă a vederii prin secționarea nervului optic."},{"id":"D","text":"Diplopie tranzitorie prin anestezia ramurii superioare a nervului oculomotor comun."},{"id":"E","text":"Lezarea globului ocular prin intrarea acului în orbită."}],"correct":["A","B","E"],"pages":[553],"source":"set-2"},{"id":"set2-ytNyGslm","fingerprint":"4294c70a5b09c3bb","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care afirmații referitoare la profunzimea și abordul pătrunderii acului în anestezia nervului infraorbital sunt adevărate?","options":[{"id":"A","text":"În puncția pe cale cutanată acul va pătrunde în canal maximum 0,5-1 cm pentru a evita intrarea în orbită."},{"id":"B","text":"În timpul tehnicii pe cale orală perceperea pătrunderii acului în canal este asigurată de fixarea policelui suborbitar."},{"id":"C","text":"Pentru anestezia dinților frontali pătrunderea acului pe cale orală în canalul infraorbital se realizează pe o distanță de 6-10 mm."},{"id":"D","text":"Nepătrunderea în canal generează o anestezie limitată exclusiv la structurile dentare fără a interesa părțile moi."},{"id":"E","text":"După realizarea contactului osos pe cale orală acul trebuie direcționat în jos înainte și înăuntru."}],"correct":["A","C"],"pages":[553],"source":"set-2"},{"id":"set2-Vp5HFgsf","fingerprint":"a20705838c5212ac","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele particularități neuro-anatomice și procedurale se aplică anesteziei nervului infraorbital?","options":[{"id":"A","text":"Nervul alveolar supero-mijlociu reprezintă o structură constantă responsabilă de inervația rădăcinii palatinale a primului molar superior."},{"id":"B","text":"Realizarea manoperelor la nivelul incisivului central superior sub această anestezie impune frecvent completarea prin anestezia nervului nazo-palatin."},{"id":"C","text":"Puncția anestezică pe cale cutanată se abordează lateral și superior de gaura infraorbitală."},{"id":"D","text":"Intervențiile chirurgicale în teritoriul de inervație necesită deseori o completare prin infiltrația fibromucoasei palatine."},{"id":"E","text":"Nervul infraorbital dă naștere la ramuri palpebrale inferioare nazale și labiale superioare la exteriorizarea prin gaura infraorbitară."}],"correct":["B","D","E"],"pages":[553],"source":"set-2"},{"id":"set2-xwPYvohf","fingerprint":"eedf807a9241a3b6","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt structurile anesteziate prin tehnica la spina Spix a nervului alveolar inferior?","options":[{"id":"A","text":"Dinții de pe o hemiarcadă"},{"id":"B","text":"Gingivomucoasa vestibulară de la gaura mentonieră la linia mediană"},{"id":"C","text":"Părțile moi labio-mentoniere"},{"id":"D","text":"Mucoasa vestibulară distal de gaura mentonieră"},{"id":"E","text":"Aria inervată de nervul bucal"}],"correct":["A","B","C"],"pages":[554],"source":"set-2"},{"id":"set2-I-KbmwqB","fingerprint":"edd898b207d06616","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Ce consecință are efectuarea puncției anestezice prea profund, la 2,5-3 cm, în timpul anesteziei nervului alveolar inferior?","options":[{"id":"A","text":"Paralizia mușchiului maseter"},{"id":"B","text":"Anestezia la nivelul laterofaringelui însoțită de tulburări de deglutiție"},{"id":"C","text":"Proptirea acului în marginea anterioară a ramului mandibular"},{"id":"D","text":"Infiltrarea glandei parotide cu pareza tranzitorie a nervului facial"},{"id":"E","text":"Anestezia nervului auriculotemporal cu anestezia pavilionului auricular"}],"correct":["D"],"pages":[554],"source":"set-2"},{"id":"set2-idK2pD0V","fingerprint":"3c594e40e73eed8f","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"În cazul erorilor de tehnică la efectuarea anesteziei la spina Spix, care dintre următoarele afirmații descriu metode de corecție sau relații cauză-efect adecvate?","options":[{"id":"A","text":"Puncția efectuată prea medial determină paralizia mușchiului maseter."},{"id":"B","text":"Puncția efectuată prea profund produce lipotimie din cauza injectării intravasculare."},{"id":"C","text":"Puncția efectuată mai jos impune reinjectarea la 0,5-1 cm superior de locul puncției inițiale."},{"id":"D","text":"Puncția efectuată mai sus determină anestezia pavilionului auricular."},{"id":"E","text":"Puncția efectuată prea lateral necesită redirecționarea vârfului acului spre posterior."}],"correct":["C","D","E"],"pages":[554],"source":"set-2"},{"id":"set2-91020Iev","fingerprint":"f4fa2ef4005ef567","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este cea mai frecventă variantă anatomică asociată inervației dinților mandibulari ce determină eșecul anesteziei la spina Spix?","options":[{"id":"A","text":"Infiltrarea fibrelor nervoase accesorii ale nervului facial la nivelul premolarilor"},{"id":"B","text":"Prezența unui canal mandibular bifid cu un orificiu mandibular accesoriu"},{"id":"C","text":"Inervația accesorie la nivelul rădăcinii meziale a molarului unu inferior prin filete din nervul milohioidian"},{"id":"D","text":"Inervația accesorie la nivelul rădăcinii distale a molarului trei inferior din nervul bucal"},{"id":"E","text":"Încrucișarea fibrelor nervoase ipsilaterale cu cele contralaterale la nivelul incisivilor inferiori"}],"correct":["C"],"pages":[554],"source":"set-2"},{"id":"set2-jfjxLVnO","fingerprint":"774b349d8bc9f01e","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la reperele și tehnica de puncție pentru anestezia nervului alveolar inferior sunt adevărate?","options":[{"id":"A","text":"La pacientul dentat, locul de puncție este situat la 1,5 cm deasupra planului de ocluzie al molarilor inferiori."},{"id":"B","text":"Plica pterigomandibulară este situată de-a lungul marginii anterioare a mușchiului pterigoidian intern."},{"id":"C","text":"Nervul lingual se anesteziază când acul ajunge la o profunzime de 1 cm."},{"id":"D","text":"Locul de puncție se află între creasta temporală și plica pterigomandibulară."},{"id":"E","text":"În timpul avansării acului, corpul seringii rămâne strict paralel cu arcada inferioară pe toată durata procedurii."}],"correct":["B","C","D"],"pages":[554],"source":"set-2"},{"id":"set2-a62zZ7-N","fingerprint":"6e770ee7dc8a9641","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la tehnica anesteziei nervului alveolar inferior pe cale submandibulară?","options":[{"id":"A","text":"Pentru a anestezia nervul alveolar inferior, acul trebuie să ajungă la o profunzime de 4,5 cm, deasupra orificiului mandibular."},{"id":"B","text":"Locul de puncție este situat la 1,5 cm de unghiul mandibular și la 1,5 cm sub marginea inferioară a mandibulei."},{"id":"C","text":"Acul de puncție trebuie să piardă contactul cu fața internă a ramului ascendent după pătrunderea inițială în țesuturi."},{"id":"D","text":"La o profunzime de 5,5 cm se realizează anestezia nervului bucal."},{"id":"E","text":"Tehnica necesită utilizarea unui ac cu o lungime de 8 cm."}],"correct":["A","B","E"],"pages":[555],"source":"set-2"},{"id":"set2-SIoEqFXu","fingerprint":"a47a76b7b338eec5","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt accidentele posibile ce pot surveni în timpul anesteziei nervului alveolar inferior pe cale retromandibulară?","options":[{"id":"A","text":"Lezarea arterei carotide interne"},{"id":"B","text":"Lezarea venei jugulare interne"},{"id":"C","text":"Pareza tranzitorie a nervului facial"},{"id":"D","text":"Lezarea venei jugulare externe"},{"id":"E","text":"Lezarea arterei carotide externe"}],"correct":["C","D","E"],"pages":[555],"source":"set-2"},{"id":"set2-gPfBdosn","fingerprint":"dbf7ac64729a8887","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele reprezintă indicații și caracteristici ale anesteziei nervului alveolar inferior pe cale cutanată și ale abordului superior?","options":[{"id":"A","text":"Anestezia pe cale cutanată este practicată exclusiv în chirurgia oro-maxilo-facială."},{"id":"B","text":"Calea superioară reprezintă abordul cel mai frecvent utilizat în practică."},{"id":"C","text":"Procedura este indicată atunci când abordul oral este imposibil, iar riscul anesteziei generale este mult prea mare în raport cu beneficiul."},{"id":"D","text":"Utilizarea căii superioare este indicată în prezența unui trismus accentuat."},{"id":"E","text":"Locul de puncție pentru calea superioară este situat deasupra arcadei temporo-zigomatice, la nivelul incizurii sigmoide."}],"correct":["A","C","D"],"pages":[555],"source":"set-2"},{"id":"set2-k48xu4B0","fingerprint":"32c7b6681acc7b0f","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este direcția de avansare a acului și profunzimea de pătrundere recomandată în tehnica anesteziei nervului alveolar inferior pe cale retromandibulară?","options":[{"id":"A","text":"Direcție verticală și spre superior, cu o profunzime de 2,5-3,5 cm."},{"id":"B","text":"Direcție orizontală și spre anterior, cu o profunzime de 2,5-3,5 cm."},{"id":"C","text":"Direcție oblică și spre medial, cu o profunzime de 1,5 cm."},{"id":"D","text":"Direcție orizontală și spre posterior, cu o profunzime de 4,5 cm."},{"id":"E","text":"Direcție orizontală și spre anterior, cu o profunzime de 5,5-6,5 cm."}],"correct":["B"],"pages":[555],"source":"set-2"},{"id":"set2-tllUp937","fingerprint":"04d06388859f24fd","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele asocieri între profunzimea de pătrundere a acului și structura vizată sunt descrise în tehnica submandibulară?","options":[{"id":"A","text":"La 4,5 cm se va anestezia nervul bucal."},{"id":"B","text":"La 4,5 cm acul ajunge mai sus de nivelul orificiului mandibular."},{"id":"C","text":"La 6,5 cm se va anestezia nervul alveolar inferior."},{"id":"D","text":"La 5,5 cm se va anestezia nervul lingual."},{"id":"E","text":"La 6,5 cm se va anestezia nervul bucal."}],"correct":["B","D","E"],"pages":[555],"source":"set-2"},{"id":"set2-KksWx5XP","fingerprint":"0aa06ba4ce408948","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următorii nervi sunt anesteziați simultan prin intermediul procedeului Veisbrem?","options":[{"id":"A","text":"Nervul alveolar inferior"},{"id":"B","text":"Nervul lingual"},{"id":"C","text":"Nervul milohioidian"},{"id":"D","text":"Nervul auriculo-temporal"},{"id":"E","text":"Nervul bucal"}],"correct":["A","B","E"],"pages":[555],"source":"set-2"},{"id":"set2-BKSy26y1","fingerprint":"f4058eae533af46a","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este dispunerea nervilor la nivelul tuberozității mandibulare, luând în considerare raporturile anatomice dinspre anterior spre posterior?","options":[{"id":"A","text":"Nervul alveolar inferior, nervul lingual, nervul bucal"},{"id":"B","text":"Nervul bucal, nervul lingual, nervul alveolar inferior"},{"id":"C","text":"Nervul lingual, nervul bucal, nervul alveolar inferior"},{"id":"D","text":"Nervul bucal, nervul alveolar inferior, nervul lingual"},{"id":"E","text":"Nervul alveolar inferior, nervul bucal, nervul lingual"}],"correct":["B"],"pages":[555],"source":"set-2"},{"id":"set2-Q-IXostp","fingerprint":"55e49b0891548bb0","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Unde se practică puncția anestezică în cadrul procedeului Veisbrem la pacienții care prezintă dinți pe arcadele dentare?","options":[{"id":"A","text":"La 1,5 cm sub creasta alveolară superioară"},{"id":"B","text":"La 1,5 cm deasupra planului de ocluzie al molarilor inferiori"},{"id":"C","text":"La 0,5 cm sub planul de ocluzie al molarilor superiori"},{"id":"D","text":"La 1,5 cm sub planul de ocluzie al molarilor superiori"},{"id":"E","text":"La 0,5 cm deasupra planului de ocluzie al molarilor inferiori"}],"correct":["B","C"],"pages":[555],"source":"set-2"},{"id":"set2-Fs7RjbpP","fingerprint":"e361388eaa50fdc8","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt elementele corecte referitoare la direcția și pătrunderea acului în timpul execuției procedeului Veisbrem?","options":[{"id":"A","text":"După injectarea primei cantități la contactul osos, acul se retrage 3-4 mm pentru a injecta restul soluției pentru nervul bucal"},{"id":"B","text":"Acul pătrunde aproximativ 1,5 cm până ia contact osos la nivelul tuberozității mandibulare"},{"id":"C","text":"Pentru anestezia nervului bucal, acul este avansat suplimentar 3-4 mm dincolo de punctul de contact osos"},{"id":"D","text":"Direcția acului este perpendiculară pe planul mucos, astfel încât corpul seringii se află în dreptul primului molar de partea opusă"},{"id":"E","text":"Corpul seringii se menține paralel cu planul de ocluzie al molarilor de pe partea pe care se efectuează puncția"}],"correct":["A","B","D"],"pages":[555],"source":"set-2"},{"id":"set2-ec00G41X","fingerprint":"52e3135f80afeb2f","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este localizarea anatomică exactă a tuberozității mandibulare descrisă ca reper în anestezia loco-regională?","options":[{"id":"A","text":"În spațiul retromolar, situată imediat posterior de ultimul molar inferior"},{"id":"B","text":"Pe fața externă a ramului mandibular, la intersecția a două creste osoase descendente"},{"id":"C","text":"La nivelul feței interne a apofizei coronoide, deasupra incizurei sigmoide"},{"id":"D","text":"Pe fața internă a ramului mandibular, la jumătatea distanței dintre incizura sigmoidă și spina Spix"},{"id":"E","text":"Pe fața internă a ramului mandibular, la jumătatea distanței dintre condilul mandibular și unghiul mandibulei"}],"correct":["D"],"pages":[555],"source":"set-2"},{"id":"set2-Gf3Isl4m","fingerprint":"4a7a568c00895d6d","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este argumentul principal care impune utilizarea procedeului Veisbrem în detrimentul anesteziei clasice la spina Spix, în contextul utilizării instrumentarului actual?","options":[{"id":"A","text":"Soluțiile din carpule au un ritm de difuziune mai accelerat exclusiv în regiunea tuberozității mandibulare"},{"id":"B","text":"Acele atraumatice produc un grad ridicat de disconfort la contactul periostal în anestezia clasică"},{"id":"C","text":"Dimensiunea redusă a carpulei conține un volum insuficient pentru blocarea nervului alveolar inferior prin tehnica clasică"},{"id":"D","text":"Procedeul modern implică pătrunderea acului la o profunzime considerabilă, de peste 3 cm, nerealizabilă în zona spinei Spix"},{"id":"E","text":"Flexibilitatea acului și mărimea ansamblului seringă - carpulă - ac nu permit efectuarea manevrelor din tehnica clasică"}],"correct":["E"],"pages":[555],"source":"set-2"},{"id":"set2-bULIi4yN","fingerprint":"fd4fc61fdef2f9a2","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt nervii anesteziați simultan prin procedeul Gow-Gates?","options":[{"id":"A","text":"Nervul infraorbital"},{"id":"B","text":"Nervul incisiv"},{"id":"C","text":"Nervul maxilar"},{"id":"D","text":"Nervul auriculotemporal"},{"id":"E","text":"Nervul alveolar inferior"}],"correct":["B","D","E"],"pages":[555,556],"source":"set-2"},{"id":"set2-_f1vTajA","fingerprint":"26ba15e210c16898","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este avantajul major al procedeului Gow-Gates comparativ cu anestezia la spina Spix?","options":[{"id":"A","text":"Previne complet riscul lezării arterei maxilare interne."},{"id":"B","text":"Elimină riscul parezei tranzitorii a nervilor cranieni oculomotori."},{"id":"C","text":"Depozitarea anestezicului se face la o distanță mai mică de 5 mm față de trunchiul nervos."},{"id":"D","text":"Timpul de instalare a anesteziei este semnificativ mai scurt."},{"id":"E","text":"Oferă o rată ridicată de succes, inclusiv în cazul inervației accesorii a dinților inferiori."}],"correct":["E"],"pages":[555,556],"source":"set-2"},{"id":"set2-3TvROWEh","fingerprint":"dd16ac5058411622","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt reperele și direcțiile corecte pentru realizarea puncției în tehnica Gow-Gates?","options":[{"id":"A","text":"Corpul seringii trebuie menținut de aceeași parte a arcadei pe care se realizează anestezia."},{"id":"B","text":"Puncția se realizează la intersecția liniei tragus-comisură bucală cu o linie ce trece la jumătatea distanței dintre plica pterigomandibulară și tendonul mușchiului temporal."},{"id":"C","text":"Absența contactului acului cu osul impune infiltrarea imediată a soluției anestezice pentru a preveni spasmul muscular."},{"id":"D","text":"Acul pătrunde în profunzime aproximativ 3-3,5 cm."},{"id":"E","text":"Depozitul anestezic se lasă la inserția mușchiului pterigoidian extern pe fața internă a condilului."}],"correct":["B","D","E"],"pages":[555,556],"source":"set-2"},{"id":"set2-sXPr_LhD","fingerprint":"c4ff70e749febbc5","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Ce complicații și cauze de eșec sunt asociate procedeului Gow-Gates?","options":[{"id":"A","text":"Lipsa instalării anesteziei cauzată de lipsa contactului acului cu osul."},{"id":"B","text":"Lezarea arterei maxilare interne la o pătrundere excesivă în profunzime."},{"id":"C","text":"Instalarea diplopiei din cauza paraliziei complete a musculaturii intrinseci a globului ocular."},{"id":"D","text":"Pareza tranzitorie a nervilor cranieni oculomotori manifestată prin blefaroptoză."},{"id":"E","text":"Necroza mucoasei obrazului la intersecția liniei tragusului cu comisura bucală."}],"correct":["A","B","D"],"pages":[555,556],"source":"set-2"},{"id":"set2-CV9jNadA","fingerprint":"2c0baf80c6e93223","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este atitudinea terapeutică obligatorie în situația în care nu se obține contactul acului cu osul în timpul puncției Gow-Gates?","options":[{"id":"A","text":"Se solicită pacientului să închidă gura pentru relaxarea mușchiului pterigoidian extern."},{"id":"B","text":"Se avansează acul suplimentar cu 5-10 mm pentru a întâlni condilul mandibular."},{"id":"C","text":"Se retrage ușor acul, se solicită deschiderea maximă a cavității orale și se palpează cu blândețe osul prin tatonare."},{"id":"D","text":"Se injectează de urgență soluția anestezică și se retrage acul."},{"id":"E","text":"Se retrage acul complet și se injectează o a doua carpulă de 1,8 ml în spațiul pterigomandibular."}],"correct":["C"],"pages":[555,556],"source":"set-2"},{"id":"set2-Da4fG-M2","fingerprint":"037dde7525820b45","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt nervii anesteziați simultan prin procedeul Vazirani-Akinosi?","options":[{"id":"A","text":"Nervul incisiv"},{"id":"B","text":"Nervul lingual"},{"id":"C","text":"Nervul milohioidian"},{"id":"D","text":"Nervul alveolar inferior"},{"id":"E","text":"Nervul maxilar"}],"correct":["A","B","C","D"],"pages":[556],"source":"set-2"},{"id":"set2-nkPaaqlv","fingerprint":"f73bd6484f11b14d","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este indicația principală pentru realizarea procedeului Vazirani-Akinosi?","options":[{"id":"A","text":"Tratamentul nevralgiei de trigemen cu localizare nazo-labială"},{"id":"B","text":"Deschiderea limitată a cavității orale"},{"id":"C","text":"Existența exclusivă a unui canal mandibular unic și rectiliniu"},{"id":"D","text":"Anestezia țesuturilor moi din treimea medie a feței"},{"id":"E","text":"Imposibilitatea vizualizării reperelor pentru anestezia nervului maxilar"}],"correct":["B"],"pages":[556],"source":"set-2"},{"id":"set2-mli6E0BA","fingerprint":"0a1ffd02e327a417","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt factorii sau incidentele care pot duce la ineficiența anesteziei sau la complicații în cadrul procedeului Vazirani-Akinosi?","options":[{"id":"A","text":"Introducerea acului de puncție medial de ligamentul sfenomandibular, cu pătrundere în spațiul pterigomaxilar"},{"id":"B","text":"Prezența unei creste temporale a mandibulei proeminente"},{"id":"C","text":"Introducerea acului de puncție lateral de ligamentul sfenomandibular"},{"id":"D","text":"Prezența unui proces zigomatic al maxilarului proeminent"},{"id":"E","text":"Injectarea accidentală a soluției anestezice în glanda parotidă prin inserția prea profundă a acului"}],"correct":["A","B","D","E"],"pages":[556],"source":"set-2"},{"id":"set2-04673Y6-","fingerprint":"b4d675ce7e2ede0a","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt reperele și detaliile tehnice ale puncției în cadrul procedeului Vazirani-Akinosi?","options":[{"id":"A","text":"Bizoul acului de puncție este orientat lateral, spre ramul mandibular"},{"id":"B","text":"Seringa se introduce paralel cu planul de ocluzie superior"},{"id":"C","text":"Acul de puncție avansează 2,5 cm menținând un contact osos ferm cu ramul mandibular"},{"id":"D","text":"Pacientul menține cavitatea orală deschisă la maximum pe tot parcursul injectării"},{"id":"E","text":"Puncția anestezică se face aproximativ la jumătatea distanței dintre gaura mandibulară și condil"}],"correct":["B","E"],"pages":[556],"source":"set-2"},{"id":"set2-l_snNvPQ","fingerprint":"67228c53a1ee8e21","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Cum se succed efectele după injectarea anestezicului în procedeul Vazirani-Akinosi?","options":[{"id":"A","text":"Dacă sensibilitatea persistă, se recomandă repetarea procedeului Vazirani-Akinosi prin abord pe aceeași parte"},{"id":"B","text":"La 2-3 minute de la infiltrarea soluției se produce anestezia filetelor nervoase motorii"},{"id":"C","text":"Anestezia filetelor senzitive se instalează prima, urmată de blocajul motor"},{"id":"D","text":"Anestezia motorie este urmată imediat de o contractură puternică a musculaturii masticatorii"},{"id":"E","text":"Relaxarea musculaturii masticatorii permite deschiderea ușoară a cavității orale"}],"correct":["B","E"],"pages":[556],"source":"set-2"},{"id":"set2-6FukhvS0","fingerprint":"8edcad4305977091","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt caracteristicile tehnicii și zonei de acțiune în anestezia de completare a nervului bucal?","options":[{"id":"A","text":"Vizează mucoasa gingivoalveolară situată mezial de gaura mentonieră."},{"id":"B","text":"Substanța anestezică este injectată profund intramuscular pentru o instalare rapidă."},{"id":"C","text":"Puncția se realizează în vestibulul inferior în dreptul premolarului doi."},{"id":"D","text":"Injectarea substanței anestezice se extinde submucos până în trigonul retromolar."},{"id":"E","text":"Vizează mucoasa gingivoalveolară situată distal de gaura mentonieră."}],"correct":["C","D","E"],"pages":[556],"source":"set-2"},{"id":"set2-4Tf1LzrO","fingerprint":"abdcb36101a52cbf","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Care este rolul principal și justificarea clinică a anesteziei nervului bucal în practica stomatologică curentă?","options":[{"id":"A","text":"Este o anestezie de bază realizată exclusiv prin abord cutanat pentru blocul nervos periferic."},{"id":"B","text":"Reprezintă o anestezie de completare în procedeul clasic de anestezie la spina Spix."},{"id":"C","text":"Este o procedură indispensabilă pentru anestezierea mucoasei situate la nivelul incisivilor centrali inferiori."},{"id":"D","text":"Se utilizează ca tehnică anestezică principală și singulară pentru intervențiile chirurgicale mandibulare extinse."},{"id":"E","text":"Constituie metoda de elecție singulară pentru suprimarea sensibilității în zonele frontale mandibulare."}],"correct":["B"],"pages":[557],"source":"set-2"},{"id":"set2-_2HawER7","fingerprint":"29157a4985e128b3","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect particularitățile anesteziei nervului bucal?","options":[{"id":"A","text":"Puncția se execută în vestibulul superior în dreptul premolarului doi."},{"id":"B","text":"Tehnicile de anestezie descrise pentru acest nerv includ atât abordul pe cale orală, cât și pe cale cutanată."},{"id":"C","text":"În practica curentă, este o anestezie de completare atunci când se practică intervenții chirurgicale."},{"id":"D","text":"Anestezia singulară a nervului bucal este indicată de rutină în procedurile stomatologice minore."},{"id":"E","text":"Abordul se realizează exclusiv pe cale orală datorită riscurilor abordului extraoral."}],"correct":["B","C"],"pages":[557],"source":"set-2"},{"id":"set2-GljzQRLT","fingerprint":"dc957801f002c1a9","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt teritoriile anatomice în care se instalează anestezia în urma blocajului separat al nervului lingual?","options":[{"id":"A","text":"Mucoasa hemiplanșeului bucal"},{"id":"B","text":"Regiunea postsulcală a hemilimbii de partea anesteziată"},{"id":"C","text":"Versantul vestibular al crestei alveolare de la ultimul molar la linia mediană"},{"id":"D","text":"Regiunea presulcală a hemilimbii de partea anesteziată"},{"id":"E","text":"Versantul lingual al crestei alveolare de la ultimul molar la linia mediană"}],"correct":["A","B","E"],"pages":[557],"source":"set-2"},{"id":"set2-sMBF3KmJ","fingerprint":"b7354e9a4d74b5e4","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele afirmații descriu corect varianta tehnică Dan Theodorescu pentru anestezia nervului lingual?","options":[{"id":"A","text":"Puncția se realizează strict la nivelul spinei Spix, la 1 cm anterior de nervul alveolar inferior"},{"id":"B","text":"Este indicată preponderent pentru intervențiile asupra porțiunii posterioare a planșeului bucal"},{"id":"C","text":"Vizează anestezia filetelor terminale ale nervului lingual"},{"id":"D","text":"Puncția anestezică se efectuează în dreptul caninului sau al primului premolar"},{"id":"E","text":"Puncția se execută în unghiul de răsfrângere a mucoasei procesului alveolar spre planșeu"}],"correct":["C","D","E"],"pages":[557],"source":"set-2"},{"id":"set2-SUG0xKcA","fingerprint":"7828f7217e79ee62","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următorii parametri și repere anatomice sunt asociați corect cu tehnicile de anestezie a nervului lingual?","options":[{"id":"A","text":"La nivelul spinei Spix, nervul lingual se află la aproximativ 1 cm posterior față de nervul alveolar inferior"},{"id":"B","text":"În șanțul mandibulo-lingual în dreptul ultimului molar, direcția acului este înapoi și ușor în afară spre os"},{"id":"C","text":"La nivelul molarului de minte, nervul lingual devine superficial înainte de a pătrunde pe sub mușchiul milohioidian în loja submandibulară"},{"id":"D","text":"Anestezia la nivelul planșeului bucal, în dreptul molarului de minte, se instalează în aproximativ 1-2 minute"},{"id":"E","text":"Cantitatea de soluție anestezică depusă în planșeul bucal, în dreptul molarului de minte, este de 1,5-2 ml"}],"correct":["B","C","D"],"pages":[557],"source":"set-2"},{"id":"set2-s6bosFNv","fingerprint":"12b22dbf789584ad","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt structurile anatomice care alcătuiesc teritoriul în care se obține anestezia după abordul nervului mentonier și incisiv?","options":[{"id":"A","text":"Fibromucoasa vestibulară între gaura mandibulară și linia mediană."},{"id":"B","text":"Dinții molari inferiori de partea anesteziată."},{"id":"C","text":"Hemibuza inferioară de partea respectivă."},{"id":"D","text":"Tegumentul regiunii mentoniere de partea respectivă."},{"id":"E","text":"Mucoasa palatină din regiunea frontală."}],"correct":["A","C","D"],"pages":[557],"source":"set-2"},{"id":"set2-c1QiUC0s","fingerprint":"78014a8ea2a385ab","chapterId":"set-2","subchapterId":"set2-7.02","type":"CS","text":"Unde este situată anatomic gaura mentonieră, care constituie reperul pentru instalarea anesteziei la acest nivel?","options":[{"id":"A","text":"La 14-15 mm distanță de linia mediană."},{"id":"B","text":"La edentați, frecvent la mijlocul distanței dintre simfiza mentonieră și marginea anterioară a mușchiului maseter."},{"id":"C","text":"Pe fața internă a corpului mandibulei."},{"id":"D","text":"Superior de linia care unește apexurile celor doi premolari inferiori."},{"id":"E","text":"La 28 mm distanță de marginea bazilară a mandibulei."}],"correct":["B"],"pages":[557],"source":"set-2"},{"id":"set2-p5gzx0kE","fingerprint":"f4ce3370438a8e61","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt reperele și detaliile tehnice corecte referitoare la anestezia nervului mentonier realizată pe cale orală?","options":[{"id":"A","text":"Puncția se realizează în mucoasa fixă din dreptul rădăcinii distale a primului molar."},{"id":"B","text":"Injectarea soluției exclusiv la nivelul găurii mentoniere produce anestezia procesului alveolar și a dinților."},{"id":"C","text":"Acul avansează având o direcție oblică în jos, înăuntru și înainte."},{"id":"D","text":"Acul formează un unghi de 15-20° cu axul premolarului doi."},{"id":"E","text":"Canalul mentonier are o orientare anatomică în sus, înapoi și în afară."}],"correct":["C","D","E"],"pages":[558],"source":"set-2"},{"id":"set2-DirEWLN7","fingerprint":"dff72d967637a8e3","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care sunt particularitățile procedurii de anestezie a nervului maseterin?","options":[{"id":"A","text":"Soluția anestezică este depozitată la o profunzime de 2,5 cm, lăsându-se 2-3 ml de lichid."},{"id":"B","text":"Soluția anestezică se injectează exclusiv înainte de a atinge mușchiul maseter."},{"id":"C","text":"Nervul maseterin este un nerv motor, iar anestezia sa este uneori necesară în prezența trismusului."},{"id":"D","text":"Puncția se practică deasupra arcadei zigomatice, posterior de tuberculul zigomatic anterior."},{"id":"E","text":"Nervul maseterin este abordat la nivelul incizurii sigmoide."}],"correct":["A","C","E"],"pages":[558],"source":"set-2"},{"id":"set2-ohh9SA1F","fingerprint":"153e455b55de76df","chapterId":"set-2","subchapterId":"set2-7.02","type":"CM","text":"Care dintre următoarele afirmații referitoare la căile de abord orală și cutanată în vederea anesteziei nervului mentonier sunt corecte?","options":[{"id":"A","text":"Puncția anestezică cutanată se face la aproximativ 2 cm înaintea comisurii bucale."},{"id":"B","text":"Calea cutanată este utilizată frecvent pentru tratamentul nevralgiei trigeminale cu zonă „trigger” mentonieră."},{"id":"C","text":"În tehnica pe cale cutanată se pătrunde în gaura mentonieră la o adâncime de 0,5-1 cm."},{"id":"D","text":"La utilizarea căii orale, pacientul acuză o fulgurație în dinții molari în momentul angajării acului în canal."},{"id":"E","text":"Direcția acului în calea cutanată este orientată în jos, înăuntru și înainte."}],"correct":["B","C","E"],"pages":[558],"source":"set-2"}];
